SELECT * FROM jsonb_to_recordset($repairs$[{"id":"4230ee7c-bf4b-4d8a-b462-eb9c4d589baf","claim_key":"cec-platform:2022:votetw-candidate-1d441124551c7592","person_id":"70110529-c329-49c1-9853-f7912540b7e0","candidate_id":"03c094a9-a6b2-4b23-9aa4-548284486d23","name":"魏嘉賢","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC1%E3%80%812%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"e2e0cf9fb76cd3c372ff008805fd8ee94936db304e98578b9fb65698ac291b65","before_md5":"796aa875007bb96d52b2652e074b3ab1","after_text":"洄瀾新昇 民心啟程\n01. 縮短城鄉醫療衛生差距，提升偏鄉地區就醫品質。\n02. 促請政府重視全民運動，加快增設各項體育設施。\n03. 督促政府開發觀光亮點，結合社群行銷發展觀光。\n04. 推動建立智慧預警系統，有效因應極端氣候傷害。\n05. 落實推動長者福利措施，保障弱勢團體基本權益。\n06. 協助地方產業創新發展，提升在地人口就業機會。\n07. 深耕節能減碳環保教育，攜手維護環境永續發展。\n08. 監督改善香榭大道缺失，重新省思花蓮城市品牌。\n09. 協助新住民適應新環境，打造職場生活友善空間。\n10. 因應少子化高齡化危機，推動長照婦幼福利政策。\n11. 推動設置智慧交通號誌，提升行車效率減少意外。\n12. 爭取預算改善警消裝備，保障警消同仁值勤安全。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","reasonCodes":["heading_or_slogan"],"excludedItemCount":1}},"items":["縮短城鄉醫療衛生差距，提升偏鄉地區就醫品質。","促請政府重視全民運動，加快增設各項體育設施。","督促政府開發觀光亮點，結合社群行銷發展觀光。","推動建立智慧預警系統，有效因應極端氣候傷害。","落實推動長者福利措施，保障弱勢團體基本權益。","協助地方產業創新發展，提升在地人口就業機會。","深耕節能減碳環保教育，攜手維護環境永續發展。","監督改善香榭大道缺失，重新省思花蓮城市品牌。","協助新住民適應新環境，打造職場生活友善空間。","因應少子化高齡化危機，推動長照婦幼福利政策。","推動設置智慧交通號誌，提升行車效率減少意外。","爭取預算改善警消裝備，保障警消同仁值勤安全。"]},{"id":"ae79614c-5765-496a-b25b-336e63596d05","claim_key":"cec-platform:2022:votetw-candidate-d15acbedd0ff5ddf","person_id":"369bd6c4-122b-4812-b4ce-c0e22a94e322","candidate_id":"09008ac4-d387-4cc1-be12-071732bb4964","name":"陳明達","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/13%E5%B1%8F%E6%9D%B1%E7%B8%A3/%E5%B1%8F%E6%9D%B1%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"132b3a73cbb10441e2b62d9316fb1831db862536766e14ea378abb1df4663ad1","before_md5":"abfc02ff80783dc7bf5b73dccafb14a0","after_text":"1、持續推動砂石車專用道路方案，保障民眾生命財產與生活品質。\n2、持續爭取65歲以上假牙補助。\n3、推動及輔導青年返鄉從農成為農業生力軍，提升產業價值與創新。\n4、創造閒置農田媒合平台提供租用，增加人才回流意願。\n5、推動農業在地品牌化，持續解決農業問題。\n6、保障女性就業、消除性騷擾與歧視、積極落實職場平等。\n7、關懷新住民文化與在地融合、生活適應、輔導家庭及孩童心理成長等。\n8、持續爭取公托及嬰幼兒完善福利制度編訂與推動，減輕家長育兒的負擔。\n9、補助客家社團、推動文化交流，加強客家母語教學，傳承提升客家意識與認同。\n10、完善屏北到高雄交通跨域網絡，持續爭取國十延伸及高屏第二快速公路。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["持續推動砂石車專用道路方案，保障民眾生命財產與生活品質。","持續爭取65歲以上假牙補助。","推動及輔導青年返鄉從農成為農業生力軍，提升產業價值與創新。","創造閒置農田媒合平台提供租用，增加人才回流意願。","推動農業在地品牌化，持續解決農業問題。","保障女性就業、消除性騷擾與歧視、積極落實職場平等。","關懷新住民文化與在地融合、生活適應、輔導家庭及孩童心理成長等。","持續爭取公托及嬰幼兒完善福利制度編訂與推動，減輕家長育兒的負擔。","補助客家社團、推動文化交流，加強客家母語教學，傳承提升客家意識與認同。","完善屏北到高雄交通跨域網絡，持續爭取國十延伸及高屏第二快速公路。"]},{"id":"53ce1876-4510-4d1b-a64c-cc6e6de1f6be","claim_key":"cec-platform:2022:votetw-candidate-fbcc195c59d1dd6e","person_id":"7efd8485-d936-4c44-bef6-e813718f278e","candidate_id":"0c1606a1-8183-4186-9ab6-a562957d5ebe","name":"許月里","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/17%E6%BE%8E%E6%B9%96%E7%B8%A3/%E6%BE%8E%E6%B9%96%E7%B8%A3%E7%AC%AC2%E3%80%813%E3%80%814%E3%80%815%E3%80%816%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"ee2c60825a1ff492417bf566a8540c7a787aa8859f0596610f4de010006aadbe","before_md5":"e95d18386c3453575332a4eeaf79812e","after_text":"疼惜西嶼，打造幸福鄉里。","split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"},"items":["疼惜西嶼，打造幸福鄉里。"]},{"id":"1c69e67e-929f-4059-a109-11531f733648","claim_key":"cec-platform:2022:votetw-candidate-89018d0fc0cead06","person_id":"f0582107-ede1-4320-b35f-c2e7ab759ba7","candidate_id":"0c7e6e33-02c2-4995-a564-753ee9341faa","name":"何春美","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/13%E5%B1%8F%E6%9D%B1%E7%B8%A3/%E5%B1%8F%E6%9D%B1%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"132b3a73cbb10441e2b62d9316fb1831db862536766e14ea378abb1df4663ad1","before_md5":"25cbd12291ce31faef3190e0c137a6db","after_text":"1.規劃麟洛鄉第二條、第三條聯外道路，以紓解屏東義大醫院營運後對當地交通之衝擊。\n2.規劃麟洛鄉埔圳巷納入公路系統並拓寬，另於南麟洛規劃一條聯外道路，以紓解台一線交通流量及提升該鄉防救災量能。\n3.建立屏北觀光，整合休閒農業、藝術、文化、產業為複合型休閒景點。\n4.督促政府重視兒童、原住民、新住民及大陳義胞權益，照顧弱勢團體及提倡兩性平權。\n5.督促政府建立農特產品產地認證及生產履歷，協助農會行銷農特產品，增加農民收益。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["規劃麟洛鄉第二條、第三條聯外道路，以紓解屏東義大醫院營運後對當地交通之衝擊。","規劃麟洛鄉埔圳巷納入公路系統並拓寬，另於南麟洛規劃一條聯外道路，以紓解台一線交通流量及提升該鄉防救災量能。","建立屏北觀光，整合休閒農業、藝術、文化、產業為複合型休閒景點。","督促政府重視兒童、原住民、新住民及大陳義胞權益，照顧弱勢團體及提倡兩性平權。","督促政府建立農特產品產地認證及生產履歷，協助農會行銷農特產品，增加農民收益。"]},{"id":"7c155fa0-6215-44ac-9e8a-f3ca969e50d0","claim_key":"cec-platform:2022:votetw-candidate-f09f542c7d50b659","person_id":"89b009c3-5143-46fc-bad4-c506172cd835","candidate_id":"13398a12-88f1-4f09-8fd0-5496a0f74d8f","name":"鄭美琴","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/07%E6%96%B0%E7%AB%B9%E7%B8%A3/%E6%96%B0%E7%AB%B9%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"5410e8a3ba596619a27b5f02bd47f10474531695ffe06008f02b307306a7ab4c","before_md5":"f43e8bc5ec662eb95398354e12117fe7","after_text":"《竹北好犀利 打造好CITY》\n☆教育升級 A++\n多元樂學、教育科技：教育科技化、快樂學習有效率。\n☆生活升級 A++\n友善共融、特色公園：城市公園化、打造舒適森活圈。\n☆交通升級 A++\n暢動便捷、宜居城市：低碳智慧化、綠色交通好順暢。\n☆福利升級 A++\n老中青幼、幸福樂活：社福多樣化、有愛無礙好生活。","split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"},"items":["教育升級 A++：多元樂學、教育科技：教育科技化、快樂學習有效率。","生活升級 A++：友善共融、特色公園：城市公園化、打造舒適森活圈。","交通升級 A++：暢動便捷、宜居城市：低碳智慧化、綠色交通好順暢。","福利升級 A++：老中青幼、幸福樂活：社福多樣化、有愛無礙好生活。"]},{"id":"8c6b760c-4d8a-41ff-811c-7b21fe0d7ad4","claim_key":"cec-platform:2022:votetw-candidate-5d8dfe6322491521","person_id":"e0e84214-1295-4aca-866d-eef7598625cf","candidate_id":"13a4cbd1-cf7a-4d8f-990a-a8615975125a","name":"高忠德 Takiludun．Anu","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC12.13.14.15%E9%81%B8%E5%8D%80.pdf","source_sha256":"ba9a3887bee3f731b69f8a20cab45fd79dd216a3636e5e8b3ca7ba04a7411766","before_md5":"ed081d8972a501edd416e0284c3b9c06","after_text":"忠德「新選擇 新希望 原民福祉看得見」\n監督市政、爭取預算，促進原住民族共同權益及利益。\n於擔任高雄市政府顧問一職，誠心溝通協調，完成多項族人陳情服務案件；高忠德忠於人民，服務重執行講效率，鄉親安心。\n政見理念：\n1、督促政府儘速修復南橫（勤和～拉芙蘭）路段為永久安全路廊，使其恢復榮景，促進部落產業發展\n2、責成市府增編部落建設經費預算，打造桃源區為宜居文化鄉城，推展原住民文化觀光產業\n3、積極爭取預算，健全桃源區部落路平專案，建設公共衛生及安全設施\n4、為確保部落生命財產安全，督促政府積極爭取各部落護岸工程經費預算\n5、營造部落年輕化，爭取資源鼓勵知識青年留在部落發展長才\n6、增設桃源區完整資訊監控系統\n7、建山里行政區土地權責移轉桃源區公所管理\n8、督促政府修復高山島農路，嘉惠農民，利興農業發展\n9、極力爭取興建高中里風雨球場\n10、設置原住民專屬假日部落市集，提供族人展示空間及行銷通路\n11、社會住宅公設空間設置原創商鋪，族人創作品有展現機會\n12、落實保障都會區族人，爭取租屋及青年創業設備補助\n13、建置政府與原住民教會之夥伴關係，寬列經費，使教會自主性辦理事務，凝聚族人向心力\n14、設立原住民人民社團同鄉會聯合辦公室，檢討並明訂各項補助規定，健全人民團體服務效能\n15、關懷大高雄原住民軍職子弟升遷及權利維護事項\n16、全力捍衛族人勞工權益，責成市府成立原住民勞工糾紛專屬諮詢服務","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","reasonCodes":["heading_or_slogan"],"excludedItemCount":1}},"items":["督促政府儘速修復南橫（勤和～拉芙蘭）路段為永久安全路廊，使其恢復榮景，促進部落產業發展","責成市府增編部落建設經費預算，打造桃源區為宜居文化鄉城，推展原住民文化觀光產業","積極爭取預算，健全桃源區部落路平專案，建設公共衛生及安全設施","為確保部落生命財產安全，督促政府積極爭取各部落護岸工程經費預算","營造部落年輕化，爭取資源鼓勵知識青年留在部落發展長才","增設桃源區完整資訊監控系統","建山里行政區土地權責移轉桃源區公所管理","督促政府修復高山島農路，嘉惠農民，利興農業發展","極力爭取興建高中里風雨球場","設置原住民專屬假日部落市集，提供族人展示空間及行銷通路","社會住宅公設空間設置原創商鋪，族人創作品有展現機會","落實保障都會區族人，爭取租屋及青年創業設備補助","建置政府與原住民教會之夥伴關係，寬列經費，使教會自主性辦理事務，凝聚族人向心力","設立原住民人民社團同鄉會聯合辦公室，檢討並明訂各項補助規定，健全人民團體服務效能","關懷大高雄原住民軍職子弟升遷及權利維護事項","全力捍衛族人勞工權益，責成市府成立原住民勞工糾紛專屬諮詢服務"]},{"id":"fa79dacd-f551-4d95-9315-d31891463bee","claim_key":"cec-platform:2022:votetw-candidate-1ba89aaa0c326adc","person_id":"f2c73fe6-9dcf-4fec-8b36-5f9aea4851fa","candidate_id":"184025fb-1f16-4c23-b993-64e4eb06fa04","name":"杜仁勇","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/13%E5%B1%8F%E6%9D%B1%E7%B8%A3/%E5%B1%8F%E6%9D%B1%E7%B8%A3%E7%AC%AC8%E3%80%8113-16%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"524f9657b4af1b226a4926022ada959412ea2880d9650209ddd4123156215480","before_md5":"ae2576337f5a553dad593e7c569a70d9","after_text":"一、專業問政，用心為民服務。\n二、協助部落推動觀光產業發展，提供青年返鄉就業機會。\n三、維護鄉民用路安全，復建災後沖毀道路、橋樑。\n四、協助改善永久屋居住空間，維護鄉民生命財產安全。\n五、維護山林國土保育，發展林下經濟。\n六、重視文化教育，傳承魯凱百合精神，延續族人命脈。\n七、爭取社會資源挹注衛生醫療、協助法律輔導，減少鄉民訟累。\n八、增進社區祥和，關懷老人福利。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","reasonCodes":["heading_or_slogan"],"excludedItemCount":2}},"items":["協助部落推動觀光產業發展，提供青年返鄉就業機會。","維護鄉民用路安全，復建災後沖毀道路、橋樑。","協助改善永久屋居住空間，維護鄉民生命財產安全。","維護山林國土保育，發展林下經濟。","重視文化教育，傳承魯凱百合精神，延續族人命脈。","爭取社會資源挹注衛生醫療、協助法律輔導，減少鄉民訟累。"]},{"id":"c742ed7c-e5c5-454f-a7c6-2decda56c55c","claim_key":"cec-platform:2022:votetw-candidate-b35de4fc1792d5ae","person_id":"d8aaa0ac-1188-4e03-85db-a8bc944ac741","candidate_id":"1bc167d2-f808-441b-b601-b5bdec9fcfc0","name":"全文才Balan．Soqluman","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/10%E5%8D%97%E6%8A%95%E7%B8%A3/%E5%8D%97%E6%8A%95%E7%B8%A3%E7%AC%AC6.7.8%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"24db9bf22b5ce5361b3a990f82789c2ea9a4605239639ccec4a1aad857a5eea8","before_md5":"af2362c6d3f5fd26aaf40b4ba43d8077","after_text":"1、秉持公平、正義與比例原則，力促縣政府落實執行地方均衡之發展。\n2、積極爭取營造原鄉特色之基礎建設，推動並扶持原鄉部落文化、生態及農業遊憩觀光產業。\n3、力促縣政府積極改善原鄉農、產業道路，以改善並活絡原鄉農業之經濟產業。\n4、力促縣政府優先改善原鄉教育環境與設備，以縮短城鄉教育資源之差距。\n5、力促縣政府積極扶持原鄉民間長照機構之設立，以落實原鄉老人及弱勢族群之起居生活與身心健康照護。\n6、力促縣政府落實都會原住民就業輔導與經濟、生活之照護。\n7、積極爭取十六省道之拓寬改善工程，以確保農產運輸與交通的安全。\n8、積極爭取濁水溪線消防分隊（站）之設立，以保障人民生命財產之安全。\n9、積極監督縣政府落實中央政府制定或推動之原住民族相關政策與事務。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["秉持公平、正義與比例原則，力促縣政府落實執行地方均衡之發展。","積極爭取營造原鄉特色之基礎建設，推動並扶持原鄉部落文化、生態及農業遊憩觀光產業。","力促縣政府積極改善原鄉農、產業道路，以改善並活絡原鄉農業之經濟產業。","力促縣政府優先改善原鄉教育環境與設備，以縮短城鄉教育資源之差距。","力促縣政府積極扶持原鄉民間長照機構之設立，以落實原鄉老人及弱勢族群之起居生活與身心健康照護。","力促縣政府落實都會原住民就業輔導與經濟、生活之照護。","積極爭取十六省道之拓寬改善工程，以確保農產運輸與交通的安全。","積極爭取濁水溪線消防分隊（站）之設立，以保障人民生命財產之安全。","積極監督縣政府落實中央政府制定或推動之原住民族相關政策與事務。"]},{"id":"12f496b9-03a6-472c-acff-aa13e012cbda","claim_key":"cec-platform:2022:votetw-candidate-a7897635f96a50f6","person_id":"27505474-0524-484a-a8b7-42434cbbeb1e","candidate_id":"25275f77-81e6-47dc-97bf-d580d83bb78d","name":"林琮翰","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/16%E8%87%BA%E6%9D%B1%E7%B8%A3/%E8%87%BA%E6%9D%B1%E7%B8%A3%E7%AC%AC1%E3%80%817%E3%80%8114%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"d205c4b47c90631192376186a2a93ea372601f08bc60a60f67be4e6788d83bb7","before_md5":"010b46a8a7ac520c7b76e1bb15b37080","after_text":"一、監督縣府落實原住民基本法及各項福利政策。\n二、關懷原住民中的弱勢團體使之能有更好的生活保障。\n三、催促縣府迅速制定原住民相關產業發展計劃。\n四、協助發展原住民部落的文創產業，讓商品更具競爭性，並能打入市場。\n五、督促縣府重視原住民教育的未來發展並讓每位原住民的下一代接受良好的教育。\n六、重視原住民的傳統文化、語言、技能及祭典儀式的傳承。\n七、捍衛有關原住民各項權益及政策，創造原住民的新未來。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["監督縣府落實原住民基本法及各項福利政策。","關懷原住民中的弱勢團體使之能有更好的生活保障。","催促縣府迅速制定原住民相關產業發展計劃。","協助發展原住民部落的文創產業，讓商品更具競爭性，並能打入市場。","督促縣府重視原住民教育的未來發展並讓每位原住民的下一代接受良好的教育。","重視原住民的傳統文化、語言、技能及祭典儀式的傳承。","捍衛有關原住民各項權益及政策，創造原住民的新未來。"]},{"id":"0deabcfa-51d9-4c7e-afb3-fbd1b9725a8e","claim_key":"cec-platform:2022:votetw-candidate-299912427d59a599","person_id":"c3df1b88-e3b7-4890-a07e-b075dcbc51b0","candidate_id":"2b45befe-5996-4d1d-aff9-bb01f448cdfa","name":"劉孟君","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/13%E5%B1%8F%E6%9D%B1%E7%B8%A3/%E5%B1%8F%E6%9D%B1%E7%B8%A3%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"c4ec4b59e24163526e3504f3d7b798532fafa689f63bcb9ab9e35628d7665151","before_md5":"8130c289188d8164adfd4a9bf1a5ee9c","after_text":"一、實踐政治參與為人民服務之理念。\n二、推動失智長者公費安置機構。\n三、推動校園安全及嚴格把關食安問題。\n四、建議縣府落實兒童與青少年生活輔導與教育。\n五、督促政府關照新移民居住學習及就業權益。\n六、協助農村、漁村再生轉為經濟型地方生創。\n七、兩性平權，提高婦女就業機會。\n八、監督縣府落實校園掃毒工作，建立學童防護毒品機制，將毒品趕出校園，保障學生身心健康。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","reasonCodes":["heading_or_slogan"],"excludedItemCount":1}},"items":["推動失智長者公費安置機構。","推動校園安全及嚴格把關食安問題。","建議縣府落實兒童與青少年生活輔導與教育。","督促政府關照新移民居住學習及就業權益。","協助農村、漁村再生轉為經濟型地方生創。","兩性平權，提高婦女就業機會。","監督縣府落實校園掃毒工作，建立學童防護毒品機制，將毒品趕出校園，保障學生身心健康。"]},{"id":"1ff757f1-b92a-4275-8db6-bfe39adc9f07","claim_key":"cec-platform:2022:votetw-candidate-259c8157f69c2ac0","person_id":"31e9d727-c39d-4e28-a329-1b4440e39976","candidate_id":"2d2ce501-f12a-4233-a9f8-e9c42e97206a","name":"張利惠","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/13%E5%B1%8F%E6%9D%B1%E7%B8%A3/%E5%B1%8F%E6%9D%B1%E7%B8%A3%E7%AC%AC08-12%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"e88361c91ca426bc3ec0b0a8a9dee4c53b92bd04e89add71890b235c11378624","before_md5":"1ed15c31f3b703bc352a92c2728c09ff","after_text":"1. 以負責、專業的從政理念，落實推動本鄉各項建設及謀取族親最大福祉。\n2. 理性問政，嚴謹監督縣政府施政，保障我原住民權益。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["以負責、專業的從政理念，落實推動本鄉各項建設及謀取族親最大福祉。","理性問政，嚴謹監督縣政府施政，保障我原住民權益。"]},{"id":"d7edb7ae-fe90-4753-9f18-adc75b92ed70","claim_key":"cec-platform:2022:votetw-candidate-8a797e9b78703364","person_id":"acefdad6-6f19-466f-8a96-b0520a1e0780","candidate_id":"354ec65c-1214-40fc-b613-2b5cb4b2590e","name":"張仁和","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/17%E6%BE%8E%E6%B9%96%E7%B8%A3/%E6%BE%8E%E6%B9%96%E7%B8%A3%E7%AC%AC2%E3%80%813%E3%80%814%E3%80%815%E3%80%816%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"ee2c60825a1ff492417bf566a8540c7a787aa8859f0596610f4de010006aadbe","before_md5":"e95d18386c3453575332a4eeaf79812e","after_text":"堅持為七美\n鄉親擺優先","split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"},"items":["堅持為七美，鄉親擺優先"]},{"id":"3513dc64-d20d-4c73-8edd-0fc578695d8d","claim_key":"cec-platform:2022:votetw-candidate-02e60de6e55edd2c","person_id":"b3164b65-a197-4476-83a4-6292b339e8d0","candidate_id":"36220eb8-3989-48b4-90c7-d364b2b0071d","name":"鄭張常敏","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/13%E5%B1%8F%E6%9D%B1%E7%B8%A3/%E5%B1%8F%E6%9D%B1%E7%B8%A3%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"c4ec4b59e24163526e3504f3d7b798532fafa689f63bcb9ab9e35628d7665151","before_md5":"2eed583bf5bebc378e6b856c939ce3b6","after_text":"一、建議政府推動農路修復路平專案，以利發展農村經濟。\n二、推動貧困弱勢家庭補助政策及落實實際查訪作業。\n三、促進社區發展公益活動，打造祥和互助的友善社區。\n四、推動各村里社區照顧關懷據點設置。\n五、促進地方文物特色發展。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["建議政府推動農路修復路平專案，以利發展農村經濟。","推動貧困弱勢家庭補助政策及落實實際查訪作業。","促進社區發展公益活動，打造祥和互助的友善社區。","推動各村里社區照顧關懷據點設置。","促進地方文物特色發展。"]},{"id":"12aac061-8b61-426e-bb95-d227dab11091","claim_key":"cec-platform:2022:votetw-candidate-beb429444886836d","person_id":"274b93cf-e419-4669-81b7-a778816899ef","candidate_id":"3b8fd225-1783-4b6d-9874-1059a2c839ae","name":"越秋女","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/13%E5%B1%8F%E6%9D%B1%E7%B8%A3/%E5%B1%8F%E6%9D%B1%E7%B8%A3%E7%AC%AC08-12%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"e88361c91ca426bc3ec0b0a8a9dee4c53b92bd04e89add71890b235c11378624","before_md5":"1ed15c31f3b703bc352a92c2728c09ff","after_text":"一、善盡代議士責任與義務—賡續全天候專職服務，落實監督縣政、專業問政，提供優質效率第一的服務。\n二、永久屋問題責無旁貸：\n1. 配合中央民意代表爭取永久屋土地所有權、督促屏東縣政府修正永久三方契約，找回居住正義。\n2. 督促屏東縣政府積極解決永久屋產業發展及空間不足之建築管理問題。\n三、青年安心：\n1. 敦請屏東縣政府成立青年政策諮詢委員會或青諮顧問，俾利因應公民權年齡下修等相關青年參政之權益。\n2. 主動關懷青年勞工相關權益及福利議題，保障青勞未來步入中年或退休後等相關補助及津貼。\n3. 爭取「來義鄉青年聚會所」在部落之心；辦理相關體育賽事，督促縣府編列體育獎勵金，改善體育環境及設施設備。\n四、長者安心：\n1. 賡續配合「醫療．長期照顧服務…」等各項完善照顧服務一體化—落實在地安老、關懷高齡者福利政策。\n2. 爭取提高重陽節各年齡層敬老禮金，重視各文健站，日托及樂智關懷據點需求。\n3. 敦促縣府善用貼心巴士，結合鄰近醫療網—推動本鄉及都會區長者居家醫療輔導計畫。\n五、觀光產業：\n1. 力推「地方創生」、整合鄉內及都會區「觀光產業」，發展各部落特色景觀主題，發展藝文亮點，培育在地藝術人文青年，協助提供舞台及展演機會，以在地人文為特色重點培育及專業設計。\n2. 爭取每年辦理大型產業推廣活動，結合地方文化特色及行銷推展本鄉農特產品，爭取本鄉與都會區部落產業市集，促進城鄉社會發展接軌。\n六、家園安全：\n1. 督促縣政府加強原居地部落安全問題，嚴格列管追蹤各項申請及陳情案，保障鄉民各項法定權益。\n2. 家園安全—賡續向中央爭取各項建設經費，落實執行縣議會提案及陳年案件，以解決鄉民需求。\n3. 爭取屏東縣政府擬定「潮州人工湖回饋金編列及運用要點」，爭取水資源源頭之來義鄉民最高權益及福祉。\n七、勞工保障—逐年寬列預算造福在外發展鄉親，關懷失業勞工就業權益，協助改善勞動環境。\n八、農業補助—敦促各項禁伐補償金、造林獎勵金、天然災害救助，應以最快速之行政程序處理，重視及關心鄉民重大權益與需求。\n九、文化教派—爭取各部落傳統民俗文化活動及各宗教預算，強化鄉內傳統民俗文化工作及社區功能。\n十、重視軍警消—賡續關心原鄉軍警消公教子弟，寬列預算資源分配；補助各校教學環境及基礎設備，落實政府全民照顧的理念。\n十一、法律扶助—提供法律諮詢，協助解決鄉親民、刑事、勞資糾紛等案件。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","reasonCodes":["heading_or_slogan"],"excludedItemCount":4}},"items":["善盡代議士責任與義務—賡續全天候專職服務，落實監督縣政、專業問政，提供優質效率第一的服務。","配合中央民意代表爭取永久屋土地所有權、督促屏東縣政府修正永久三方契約，找回居住正義。","督促屏東縣政府積極解決永久屋產業發展及空間不足之建築管理問題。","敦請屏東縣政府成立青年政策諮詢委員會或青諮顧問，俾利因應公民權年齡下修等相關青年參政之權益。","主動關懷青年勞工相關權益及福利議題，保障青勞未來步入中年或退休後等相關補助及津貼。","爭取「來義鄉青年聚會所」在部落之心；辦理相關體育賽事，督促縣府編列體育獎勵金，改善體育環境及設施設備。","賡續配合「醫療．長期照顧服務…」等各項完善照顧服務一體化—落實在地安老、關懷高齡者福利政策。","爭取提高重陽節各年齡層敬老禮金，重視各文健站，日托及樂智關懷據點需求。","敦促縣府善用貼心巴士，結合鄰近醫療網—推動本鄉及都會區長者居家醫療輔導計畫。","力推「地方創生」、整合鄉內及都會區「觀光產業」，發展各部落特色景觀主題，發展藝文亮點，培育在地藝術人文青年，協助提供舞台及展演機會，以在地人文為特色重點培育及專業設計。","爭取每年辦理大型產業推廣活動，結合地方文化特色及行銷推展本鄉農特產品，爭取本鄉與都會區部落產業市集，促進城鄉社會發展接軌。","家園安全：督促縣政府加強原居地部落安全問題，嚴格列管追蹤各項申請及陳情案，保障鄉民各項法定權益。","家園安全：家園安全—賡續向中央爭取各項建設經費，落實執行縣議會提案及陳年案件，以解決鄉民需求。","家園安全：爭取屏東縣政府擬定「潮州人工湖回饋金編列及運用要點」，爭取水資源源頭之來義鄉民最高權益及福祉。","家園安全：勞工保障—逐年寬列預算造福在外發展鄉親，關懷失業勞工就業權益，協助改善勞動環境。","家園安全：農業補助—敦促各項禁伐補償金、造林獎勵金、天然災害救助，應以最快速之行政程序處理，重視及關心鄉民重大權益與需求。","家園安全：文化教派—爭取各部落傳統民俗文化活動及各宗教預算，強化鄉內傳統民俗文化工作及社區功能。","家園安全：重視軍警消—賡續關心原鄉軍警消公教子弟，寬列預算資源分配；補助各校教學環境及基礎設備，落實政府全民照顧的理念。","家園安全：法律扶助—提供法律諮詢，協助解決鄉親民、刑事、勞資糾紛等案件。"]},{"id":"81ba6f2f-7050-4fc5-b0f5-2f88b47ad520","claim_key":"cec-platform:2022:votetw-candidate-77edc6db5520fb31","person_id":"a4864953-047d-4462-a763-1473aaa03d0e","candidate_id":"476d2ea2-5ccd-4846-8f05-18a7abb5e61a","name":"張良印","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/07%E6%96%B0%E7%AB%B9%E7%B8%A3/%E6%96%B0%E7%AB%B9%E7%B8%A3%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"ff6246700ea3d9fdaf30a00c0ab72d0754509f0f4b62fd70267b2770f8b1ea50","before_md5":"0bd24f7987ee16007064036ef3a1f0ec","after_text":"1. 推動內灣聯外道路拓寬新闢工程計畫。\n2. 針對少子化影響偏鄉教育資源不足的問題積極爭取各項因應措施。\n3. 持續強化銀髮照護推動關懷據點及老人共餐服務。\n4. 積極爭取尖石鄉設置客家多元活動中心發揚在地客家傳統文化。\n5. 推動地方發展及活化歷史建築物再利用結合周邊商圈等文化景點資源帶動內灣商圈觀光效益打造內灣所成為文化觀光亮點。\n6. 推廣在地農產品協助農民提升農作產值與行銷。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["推動內灣聯外道路拓寬新闢工程計畫。","針對少子化影響偏鄉教育資源不足的問題積極爭取各項因應措施。","持續強化銀髮照護推動關懷據點及老人共餐服務。","積極爭取尖石鄉設置客家多元活動中心發揚在地客家傳統文化。","推動地方發展及活化歷史建築物再利用結合周邊商圈等文化景點資源帶動內灣商圈觀光效益打造內灣所成為文化觀光亮點。","推廣在地農產品協助農民提升農作產值與行銷。"]},{"id":"f7228b9d-ff25-4a88-bd04-7a130b15cb2d","claim_key":"cec-platform:2022:votetw-candidate-ba7a8749103e5a8d","person_id":"37d04f31-a67e-4cc4-ae91-5906599ad3e6","candidate_id":"4a1847b2-b316-4198-a312-da21df1124a5","name":"林蔡鳯梅","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/13%E5%B1%8F%E6%9D%B1%E7%B8%A3/%E5%B1%8F%E6%9D%B1%E7%B8%A3%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"c4ec4b59e24163526e3504f3d7b798532fafa689f63bcb9ab9e35628d7665151","before_md5":"9fb0196e0a90d2cde6d47aef7f29cb0d","after_text":"■信守承諾\n延續老議長林清都的政治理念為鄉親打拼。\n■陽光問政\n為農民勞工與漁友兄姊伸張正義維護權益。\n■爭取建設\n1.改善東港鹽埔漁港泊區為現代化漁港，持續發展東港漁業。\n2.興建東港低溫拍賣魚市場，確保水產品衛生品質，建立漁業新形象。\n3.改建東港老舊圖書館，新建在地特色之圖書藝文展演文化中心，提升教育文化水準。\n■督促政府\n1.加速開發大鵬灣，發展觀光振興經濟，增加地方就業機會。\n2.加速興建東港地區行政中心（王船文化館、縣屬機關聯合辦公大樓、轉運中心、社會福利綜合館及立體停車場等新建案），並重視公共工程品質，早日改善鄉親洽公環境及提升行政效率。\n3.推動農漁產業升級永續經營，帶動地方發展。\n4.重視老人婦幼及身心障礙者等弱勢團體之福利政策。\n5.重視地方治安與教學環境改善工作。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["■信守承諾 延續老議長林清都的政治理念為鄉親打拼。 ■陽光問政 為農民勞工與漁友兄姊伸張正義維護權益。","■爭取建設：改善東港鹽埔漁港泊區為現代化漁港，持續發展東港漁業。","■爭取建設：興建東港低溫拍賣魚市場，確保水產品衛生品質，建立漁業新形象。","■爭取建設：改建東港老舊圖書館，新建在地特色之圖書藝文展演文化中心，提升教育文化水準。 ■督促政府","■爭取建設：加速開發大鵬灣，發展觀光振興經濟，增加地方就業機會。","■爭取建設：加速興建東港地區行政中心（王船文化館、縣屬機關聯合辦公大樓、轉運中心、社會福利綜合館及立體停車場等新建案），並重視公共工程品質，早日改善鄉親洽公環境及提升行政效率。","■爭取建設：推動農漁產業升級永續經營，帶動地方發展。","■爭取建設：重視老人婦幼及身心障礙者等弱勢團體之福利政策。","■爭取建設：重視地方治安與教學環境改善工作。"]},{"id":"7dd6e5a9-06bf-4acf-a7e3-7308412a617f","claim_key":"cec-platform:2022:votetw-candidate-4b92d77edcaf23d6","person_id":"56a4ff10-bc7a-493a-9211-72f415c1a07b","candidate_id":"4c895fbf-35d5-4019-8225-d2a3eecc71ef","name":"宋麗華","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/13%E5%B1%8F%E6%9D%B1%E7%B8%A3/%E5%B1%8F%E6%9D%B1%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"132b3a73cbb10441e2b62d9316fb1831db862536766e14ea378abb1df4663ad1","before_md5":"ff2c4788b320bfdcde7429791aa90509","after_text":"一、實踐清廉政治生態－破除鑽營私利與勾結，邀全民參與縣政計畫。（政治）\n二、規劃半島輕軌火車－解決南臺灣交通瓶頸，鏈結地方產業與觀光。（觀光）\n三、產銷農漁畜牧花果－提振屏東物產銷售量，拓展海內外銷售市場。（經濟）\n四、實現多元族群融合－檢視聚落開發與缺失，尊重各部落文化遺產。（族群）\n五、完善科技醫療體系－社區衛教醫療與安養，老幼婦孺照護能並重。（醫療）\n六、活絡傳統記憶場域－活絡閩客原生活空間，重塑失落的社區樣貌。（社區）\n七、推動青創產業再生－以數位網路行銷專案，穩定生產與行銷鏈結。（青創）\n八、體育運動基礎建設－辦理六堆原民及縣運，再創造屏東運動大縣。（體育）\n九、國際教育雙語交流－開發國際化教育資源，深化姊妹連結與合作。（教育）\n十、擘劃文化藝術再生－完善青少年藝術教育，提供能進入國際市場。（文化）\n十一、教育政見：0～6歲免費入學，強化監督國中小營養午餐菜色品質，強化留校課後輔導師資及點心補助，建議外師普及化，提升雙語口說能力。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["實踐清廉政治生態－破除鑽營私利與勾結，邀全民參與縣政計畫。（政治）","規劃半島輕軌火車－解決南臺灣交通瓶頸，鏈結地方產業與觀光。（觀光）","產銷農漁畜牧花果－提振屏東物產銷售量，拓展海內外銷售市場。（經濟）","實現多元族群融合－檢視聚落開發與缺失，尊重各部落文化遺產。（族群）","完善科技醫療體系－社區衛教醫療與安養，老幼婦孺照護能並重。（醫療）","活絡傳統記憶場域－活絡閩客原生活空間，重塑失落的社區樣貌。（社區）","推動青創產業再生－以數位網路行銷專案，穩定生產與行銷鏈結。（青創）","體育運動基礎建設－辦理六堆原民及縣運，再創造屏東運動大縣。（體育）","國際教育雙語交流－開發國際化教育資源，深化姊妹連結與合作。（教育）","擘劃文化藝術再生－完善青少年藝術教育，提供能進入國際市場。（文化）","教育政見：0～6歲免費入學，強化監督國中小營養午餐菜色品質，強化留校課後輔導師資及點心補助，建議外師普及化，提升雙語口說能力。"]},{"id":"9efba907-a4f9-4d23-bef8-538283fd9b88","claim_key":"cec-platform:2022:votetw-candidate-c1b47ca9fc463745","person_id":"3b29697d-9d6e-4218-b2dd-352c8c1d0878","candidate_id":"4d44e69b-43ee-47d5-bff1-f9e0ff8a9dce","name":"劉陳昭玲","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/17%E6%BE%8E%E6%B9%96%E7%B8%A3/%E6%BE%8E%E6%B9%96%E7%B8%A3%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"c9aaaf6c72d2713702c0c6972ecd2623433b8ae7f029e561144dca9cba9877d8","before_md5":"d78393536eafb533b0f84ccfb8385223","after_text":"一、積極爭取經費，充足澎湖醫療在地化設備儀器。\n二、全力爭取澎湖休憩運動園區興建，塑造廣泛多功能休憩運動場域。\n三、反映爭取澎防部、後備指揮部土地釋出，提供開發利用。\n四、積極爭取經費，落實長照軟硬體設施興建及服務需求。\n五、全力推動全民運動館興建，建構充實運動環境與設施。\n六、督促縣府研議照護原住民、殘障、老弱、婦幼、榮民、外配等族群福利措施。\n七、督促落實澎湖縣國土整體規劃工作，維護鄉親權益。\n八、要求落實海洋復育措施，全力活化海洋漁業資源。\n九、爭取公共設施用地與保安林地解編，促進土地合理利用，保障民眾權益。\n十、積極推動設置污水回收處理中心，營造優質生活環境，潔淨地區海洋生態。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["積極爭取經費，充足澎湖醫療在地化設備儀器。","全力爭取澎湖休憩運動園區興建，塑造廣泛多功能休憩運動場域。","反映爭取澎防部、後備指揮部土地釋出，提供開發利用。","積極爭取經費，落實長照軟硬體設施興建及服務需求。","全力推動全民運動館興建，建構充實運動環境與設施。","督促縣府研議照護原住民、殘障、老弱、婦幼、榮民、外配等族群福利措施。","督促落實澎湖縣國土整體規劃工作，維護鄉親權益。","要求落實海洋復育措施，全力活化海洋漁業資源。","爭取公共設施用地與保安林地解編，促進土地合理利用，保障民眾權益。","積極推動設置污水回收處理中心，營造優質生活環境，潔淨地區海洋生態。"]},{"id":"a0beed75-c895-44b3-a5b9-141cc91ad35d","claim_key":"cec-platform:2022:votetw-candidate-eb7cc15eeae657d5","person_id":"bc577072-d7e9-4366-937a-79eb35d2d9b2","candidate_id":"5616b263-b60a-4bd7-aa68-6096029ff4e6","name":"藍凱元","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/17%E6%BE%8E%E6%B9%96%E7%B8%A3/%E6%BE%8E%E6%B9%96%E7%B8%A3%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"c9aaaf6c72d2713702c0c6972ecd2623433b8ae7f029e561144dca9cba9877d8","before_md5":"d4dc8039a84708b5baa2d4ed5a25a369","after_text":"監督縣政，為民喉舌\n重視教育，培育人才\n振興經濟，永續觀光\n關懷弱勢，服務鄉親","split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"},"items":["監督縣政，為民喉舌","重視教育，培育人才","振興經濟，永續觀光","關懷弱勢，服務鄉親"]},{"id":"0ce50d85-a26f-484c-9e65-124be2a93f74","claim_key":"cec-platform:2022:votetw-candidate-7c8be11dd1934eee","person_id":"6b05d0f8-4fc3-4b73-aefc-b347796f5147","candidate_id":"5c228be3-a212-4192-a414-478cee65ab63","name":"金淑敏","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC8-10%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"643ee9ae4f9200feb8d2143d4014b505638b1851f5a648179afad42e444e3289","before_md5":"105bac59734896ed4eb19d442384ff76","after_text":"護權益 顧民生\n1. 促請設立卓溪鄉老人長照中心，建置「醫養合一」照護機制，讓老人能在自己家鄉安老，讓照護更安心，實現長照在地化。\n2. 促請改善原鄉照服員薪資及勞動條件、精進服務模式、強化人力培育及技職訓練，滿足原鄉及偏遠地區長照需求。\n3. 後疫情時代各項產業環境變化，爭取加強原住民族亮點產業推升計畫，設置部落行銷據點，開展創新投資、創造經濟動能。\n4. 後疫情產業發展策略：爭取配合輔助政策計畫鼓勵創業投資，促進產業升級，振興部落經濟發展，穩定部落生計。\n5. 爭取智慧農業輔導團隊，設立部落－生技有機農場，增進部落種植技藝、農地畜產管銷技術，增加部落婦女及族人收入。\n6. 爭取環境永續、產業創新、運用部落生態優勢環境資源，輔導部落種植高經濟作物，加強現有特用作物品質產銷多元發展。\n7. 面對極端氣候環境衝擊，部落簡水及農灌水源，遭受暴雨沖刷，地質變動，年年水荒，生計深陷困境，促請政府勇於面對從速從優檢視水荒困境地區，全面改善部落人民民生用水。\n8. 面臨高齡社會，爭取設立「原鄉國際慈悲關懷」部落，建置部落追求互信合力醫到宅 老終安目標，關懷長者、身障者、弱勢族群及社會邊緣人，提供完善的人性關懷服務。\n9. 國土計畫法114年4月30日制度實施，促請重視原住民傳統領域土地劃設、適度調整及放寬農地變建地之變更、更正編定政策，並加強化社聚落居住環境土地，因應部落居住需求。\n10. 促請加強督促申辦增劃編原住民保留地辦理進度與稽核機制，依法處理核配不實取得耕作權與所有權之土地，杜絕侵權。\n11. 爭取設立平地鄉鎮山地原住民聯誼中心基地與設施，提供族人生活關懷照護聯繫、留鄉青年子女各技職資源培訓，民族文化技藝傳承學習與諮詢服務平台。\n12. 為落實原住民族教育，運用脈絡戮力向上級爭取各項資源及經費推動原鄉教育、充實在地產業、地方教育、民族文化等資源。為促進花蓮縣原鄉農業部落產業發展，促請政府重視小農特殊化、強調品種特殊性，做好花蓮縣農業三品三專（品種專有、品牌專區、品質專業）讓花蓮縣的商品有更好的價值、奠定花蓮縣休閒農業發展的基礎。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["護權益 顧民生：促請設立卓溪鄉老人長照中心，建置「醫養合一」照護機制，讓老人能在自己家鄉安老，讓照護更安心，實現長照在地化。","護權益 顧民生：促請改善原鄉照服員薪資及勞動條件、精進服務模式、強化人力培育及技職訓練，滿足原鄉及偏遠地區長照需求。","護權益 顧民生：後疫情時代各項產業環境變化，爭取加強原住民族亮點產業推升計畫，設置部落行銷據點，開展創新投資、創造經濟動能。","護權益 顧民生：後疫情產業發展策略：爭取配合輔助政策計畫鼓勵創業投資，促進產業升級，振興部落經濟發展，穩定部落生計。","護權益 顧民生：爭取智慧農業輔導團隊，設立部落－生技有機農場，增進部落種植技藝、農地畜產管銷技術，增加部落婦女及族人收入。","護權益 顧民生：爭取環境永續、產業創新、運用部落生態優勢環境資源，輔導部落種植高經濟作物，加強現有特用作物品質產銷多元發展。","護權益 顧民生：面對極端氣候環境衝擊，部落簡水及農灌水源，遭受暴雨沖刷，地質變動，年年水荒，生計深陷困境，促請政府勇於面對從速從優檢視水荒困境地區，全面改善部落人民民生用水。","護權益 顧民生：面臨高齡社會，爭取設立「原鄉國際慈悲關懷」部落，建置部落追求互信合力醫到宅 老終安目標，關懷長者、身障者、弱勢族群及社會邊緣人，提供完善的人性關懷服務。","護權益 顧民生：國土計畫法114年4月30日制度實施，促請重視原住民傳統領域土地劃設、適度調整及放寬農地變建地之變更、更正編定政策，並加強化社聚落居住環境土地，因應部落居住需求。","護權益 顧民生：促請加強督促申辦增劃編原住民保留地辦理進度與稽核機制，依法處理核配不實取得耕作權與所有權之土地，杜絕侵權。","護權益 顧民生：爭取設立平地鄉鎮山地原住民聯誼中心基地與設施，提供族人生活關懷照護聯繫、留鄉青年子女各技職資源培訓，民族文化技藝傳承學習與諮詢服務平台。","護權益 顧民生：為落實原住民族教育，運用脈絡戮力向上級爭取各項資源及經費推動原鄉教育、充實在地產業、地方教育、民族文化等資源。為促進花蓮縣原鄉農業部落產業發展，促請政府重視小農特殊化、強調品種特殊性，做好花蓮縣農業三品三專（品種專有、品牌專區、品質專業）讓花蓮縣的商品有更好的價值、奠定花蓮縣休閒農業發展的基礎。"]},{"id":"6bc96bc9-98c5-4bb2-b030-77eb60ebbdee","claim_key":"cec-platform:2022:votetw-candidate-f4fb0bc3fad2f0e1","person_id":"11b504f7-7a7b-4aa6-bdc2-1f53f433fdae","candidate_id":"5c4edcff-63ef-4c35-bba9-c195b3e18756","name":"張鎮榮","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/07%E6%96%B0%E7%AB%B9%E7%B8%A3/%E6%96%B0%E7%AB%B9%E7%B8%A3%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"69576cd0a3ab504ac5d01e56cda7f1cbc1a7e1f2bc76b53f8d5cd276a2844116","before_md5":"e998ecb8840c08fc0176815669353e40","after_text":"1. 打造本縣濱海地區繁榮與發展，串連桃園市、新竹市與本縣濱海休閒廊道，建設新豐鄉坡頭觀光休閒漁港。\n2. 督促縣府儘速完成台1線替代道路新闢工程。\n3. 增設公立以及非營利幼兒園。\n4. 促成新豐鄉掩埋場轉型綠能經營再生觀光工廠。\n5. 學童免費營養午餐。\n6. 新豐鄉內主要幹道電纜地下化。\n7. 督促縣府完成新豐鄉坡頭村石滬親水空間改善計劃。\n8. 打造具本鄉特色文化觀光老街。\n9. 廣設縣內長期照顧2.0服務及社區關懷據點。\n10. 提高鄉內瓦斯天然氣管線普及率。\n11. 提昇新豐鄉社區活動中心設備。\n12. 督促縣府加速完成新豐鄉台61線與台15線銜接道路拓寬工程。\n13. 督促縣府輔導新豐鄉辦理農產品推廣活動，以提昇整體的農業經濟價值。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","reasonCodes":["heading_or_slogan"],"excludedItemCount":3}},"items":["打造本縣濱海地區繁榮與發展，串連桃園市、新竹市與本縣濱海休閒廊道，建設新豐鄉坡頭觀光休閒漁港。","督促縣府儘速完成台1線替代道路新闢工程。","增設公立以及非營利幼兒園。","促成新豐鄉掩埋場轉型綠能經營再生觀光工廠。","督促縣府完成新豐鄉坡頭村石滬親水空間改善計劃。","打造具本鄉特色文化觀光老街。","廣設縣內長期照顧2.0服務及社區關懷據點。","提高鄉內瓦斯天然氣管線普及率。","督促縣府加速完成新豐鄉台61線與台15線銜接道路拓寬工程。","督促縣府輔導新豐鄉辦理農產品推廣活動，以提昇整體的農業經濟價值。"]},{"id":"e214666a-5bc8-4835-8e88-5eaafc334bb7","claim_key":"cec-platform:2022:votetw-candidate-8fde1c92e038c6fd","person_id":"90807dfe-7490-46a0-aaa2-4635d7fcbdac","candidate_id":"5c5fd4f4-98a1-4bc4-80ad-65814ec0e259","name":"簡智隆","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC8-10%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"643ee9ae4f9200feb8d2143d4014b505638b1851f5a648179afad42e444e3289","before_md5":"105bac59734896ed4eb19d442384ff76","after_text":"監督、連結、媒合、推動\n以誠摯的心，為族人服務","split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"},"items":["監督、連結、媒合、推動","以誠摯的心，為族人服務"]},{"id":"067bde29-67f5-4dc4-9c12-4ec45ce18a7e","claim_key":"cec-platform:2022:votetw-candidate-9c14318eabb01b7e","person_id":"ca3d39d8-2c79-4be4-a221-03d305a85b35","candidate_id":"5e436f77-cd25-4010-9fb9-f9c9a514acb7","name":"蘇孟婕","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/13%E5%B1%8F%E6%9D%B1%E7%B8%A3/%E5%B1%8F%E6%9D%B1%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"132b3a73cbb10441e2b62d9316fb1831db862536766e14ea378abb1df4663ad1","before_md5":"660b3d6ac09ecc61c807f4b2f199e37c","after_text":"服務有婕\n在地就業\n爭取屏科園區錄取本區居民\n促進產學合作，鼓勵在地就業\n創生地方\n發揚地方特色，爭取各級補助\n農業產銷升級，鼓勵青年創業\n安養生活\n爭取擴大敬老補助\n假牙、老花眼鏡、助聽器等老年安養補助從優從寬","split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"},"items":["在地就業：爭取屏科園區錄取本區居民","在地就業：促進產學合作，鼓勵在地就業","創生地方：發揚地方特色，爭取各級補助","創生地方：農業產銷升級，鼓勵青年創業","安養生活：爭取擴大敬老補助","安養生活：假牙、老花眼鏡、助聽器等老年安養補助從優從寬"]},{"id":"5ac621da-e0c7-4e1e-9987-8b609da725a8","claim_key":"cec-platform:2022:votetw-candidate-4102fff0db36f0da","person_id":"513ca88f-8580-4376-8d85-49b7620ae837","candidate_id":"622e4b62-0bde-4c13-98cb-86104d12ae07","name":"蔡清續","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/17%E6%BE%8E%E6%B9%96%E7%B8%A3/%E6%BE%8E%E6%B9%96%E7%B8%A3%E7%AC%AC2%E3%80%813%E3%80%814%E3%80%815%E3%80%816%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"ee2c60825a1ff492417bf566a8540c7a787aa8859f0596610f4de010006aadbe","before_md5":"e95d18386c3453575332a4eeaf79812e","after_text":"一、促進大湖西觀光園區，將湖西荷塘、湖東荸薺窟、青螺濕地國寶級紅樹林公園、北寮奎壁山、菓葉日出、龍門鼓浪、林投公園、隘門金沙灘，串連成一條觀光動線，帶動大湖西商機。\n二、開發湖東村湖西村之船頭尾為滯洪池，達成蓄水保持原始生態，避免天然災害。\n三、活化湖西鄉農業區廢耕地，帶動強化農產品復育及一村一特色。\n四、汰換湖西各社區路燈、木桿、架空線路燈改為線路地下化，並朝設置FRP燈桿及LED路燈等照明設施，以達成安全、美化、環保、省電效率。\n五、汰舊換新湖西鄉各社區自來水飲用管線，確保飲用水質安全，維護鄉親身心權益。\n六、規劃建設湖西鄉各社區污水下水道，經污水處理場完成淨化後，藉以灌溉農作物，餘水排放大海，以維持潔淨海底生態。\n七、強化社會福利措施，照護弱勢族群。\n八、爭取上級經費，多元行銷湖西鄉，提高知名度與能見度。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["促進大湖西觀光園區，將湖西荷塘、湖東荸薺窟、青螺濕地國寶級紅樹林公園、北寮奎壁山、菓葉日出、龍門鼓浪、林投公園、隘門金沙灘，串連成一條觀光動線，帶動大湖西商機。","開發湖東村湖西村之船頭尾為滯洪池，達成蓄水保持原始生態，避免天然災害。","活化湖西鄉農業區廢耕地，帶動強化農產品復育及一村一特色。","汰換湖西各社區路燈、木桿、架空線路燈改為線路地下化，並朝設置FRP燈桿及LED路燈等照明設施，以達成安全、美化、環保、省電效率。","汰舊換新湖西鄉各社區自來水飲用管線，確保飲用水質安全，維護鄉親身心權益。","規劃建設湖西鄉各社區污水下水道，經污水處理場完成淨化後，藉以灌溉農作物，餘水排放大海，以維持潔淨海底生態。","強化社會福利措施，照護弱勢族群。","爭取上級經費，多元行銷湖西鄉，提高知名度與能見度。"]},{"id":"d69ffd05-0446-490e-bc96-b9b01f1a8938","claim_key":"cec-platform:2022:votetw-candidate-e19afbca412a80fd","person_id":"c8554386-7f72-4791-a807-a67bab0861e2","candidate_id":"695bc342-c584-4235-bc42-783d4389e18f","name":"邱毓興","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/08%E8%8B%97%E6%A0%97%E7%B8%A3/%E7%AC%AC4%E9%81%B8%E8%88%89%E5%8D%80/%E7%AC%AC4%E9%81%B8%E8%88%89%E5%8D%80%E8%AD%B0%E5%93%A1%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf","source_sha256":"16311b8917ae90795db55be15fb97cf8a8742aa18d3d6e4ba3b75c7a7a44b09b","before_md5":"fe5d60bc7fd62546b899b6652b297f82","after_text":"打造未來 煥然一興\n一、增加親子遊憩設施：爭取新建親子生活館，同時檢視現有親子遊憩設施不足之處，並設法加以改善。\n二、爭取提高生育津貼及喪葬補助：為了提高縣內生育率，應提高生育津貼；並提高喪葬補助減輕家庭經濟負擔。\n三、爭取恢復國中、小營養午餐免費：檢視縣府財政，用於補助國中、小營養午餐免費之經費。\n四、爭取增設公托及臨托中心：落實中央0-6歲國家一起養政策，減輕雙薪家庭照顧幼兒負擔。\n五、單項體育運動推廣：推動落實三級制，讓優秀選手得以留在苗栗縣為縣爭光。\n六、醫療資源整合：積極爭取設置急重症醫療中心及老人醫療照護中心。\n七、爭取藥師公會定期辦理用藥安全宣導：協調藥師公會定期至社區及關懷據點舉辦用藥安全宣導，讓民眾更加了解用藥安全的重要性。\n八、檢視並落實社區關懷據點：協助爭取更多經費提供更多元的樂齡學習課程，不僅是知識的增長，亦是心靈的滋養。\n九、爭取每年於竹南舉辦啤酒節：爭取竹南啤酒廠與縣府合辦啤酒節，打造夏季音樂派對，期望此活動成為全台重要盛事。\n十、打通海岸線自行車道：將極力爭取經費補助，完善區域內各景點設施，同時藉由打通自行車道來吸引遊客到此觀光遊憩。\n十一、活化閒置空間：盤點縣內的閒置空間，進行活化改造，引進文創產業也推廣地方創生。\n十二、督促改善各鄉鎮市街容美觀：督促縣府與台電公司及各家電信業者協商，將電纜線得以地下化。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["打造未來 煥然一興","增加親子遊憩設施：爭取新建親子生活館，同時檢視現有親子遊憩設施不足之處，並設法加以改善。","爭取提高生育津貼及喪葬補助：為了提高縣內生育率，應提高生育津貼；並提高喪葬補助減輕家庭經濟負擔。","爭取恢復國中、小營養午餐免費：檢視縣府財政，用於補助國中、小營養午餐免費之經費。","爭取增設公托及臨托中心：落實中央0-6歲國家一起養政策，減輕雙薪家庭照顧幼兒負擔。","單項體育運動推廣：推動落實三級制，讓優秀選手得以留在苗栗縣為縣爭光。","醫療資源整合：積極爭取設置急重症醫療中心及老人醫療照護中心。","爭取藥師公會定期辦理用藥安全宣導：協調藥師公會定期至社區及關懷據點舉辦用藥安全宣導，讓民眾更加了解用藥安全的重要性。","檢視並落實社區關懷據點：協助爭取更多經費提供更多元的樂齡學習課程，不僅是知識的增長，亦是心靈的滋養。","爭取每年於竹南舉辦啤酒節：爭取竹南啤酒廠與縣府合辦啤酒節，打造夏季音樂派對，期望此活動成為全台重要盛事。","打通海岸線自行車道：將極力爭取經費補助，完善區域內各景點設施，同時藉由打通自行車道來吸引遊客到此觀光遊憩。","活化閒置空間：盤點縣內的閒置空間，進行活化改造，引進文創產業也推廣地方創生。","督促改善各鄉鎮市街容美觀：督促縣府與台電公司及各家電信業者協商，將電纜線得以地下化。"]},{"id":"9270cd21-dbf3-4f68-9ebb-e6ea1bb446fc","claim_key":"cec-platform:2022:votetw-candidate-29f9582937c88613","person_id":"ea110062-2bf2-47f5-8917-de505b6c5dff","candidate_id":"6db18817-7cc1-42f3-bf4e-b704a63cf3ba","name":"陳春暖","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/08%E8%8B%97%E6%A0%97%E7%B8%A3/%E7%AC%AC2%E3%80%813%E3%80%816%E9%81%B8%E8%88%89%E5%8D%80/%E7%AC%AC2%E3%80%813%E3%80%816%E9%81%B8%E8%88%89%E5%8D%80%E8%AD%B0%E5%93%A1%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf","source_sha256":"916c8f52e7e1901418836a498701345f057ec0a5abef661ec6d2384a6781fe87","before_md5":"ae8806f261eb88d1f44648215564dd71","after_text":"1.監督苗栗縣財政避免繼續惡化。\n2.爭取興建水果博物館，促進卓蘭觀光產業發展。\n3.爭取經費打造鯉魚潭水庫遊憩景點及周邊產業資源永續發展。\n4.爭取大湖興建週邊道路，疏困長久以來塞車問題。\n5.輔導青年返鄉從農，協助農村社區人文生態創意，成為農業生力軍。\n6.積極推動各社區成立關懷據點，落實照顧社區長輩施政主軸。\n7.努力推動臺灣正名運動。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["監督苗栗縣財政避免繼續惡化。","爭取興建水果博物館，促進卓蘭觀光產業發展。","爭取經費打造鯉魚潭水庫遊憩景點及周邊產業資源永續發展。","爭取大湖興建週邊道路，疏困長久以來塞車問題。","輔導青年返鄉從農，協助農村社區人文生態創意，成為農業生力軍。","積極推動各社區成立關懷據點，落實照顧社區長輩施政主軸。","努力推動臺灣正名運動。"]},{"id":"a370fdd7-8d8a-4cc0-8c35-614f50c225d2","claim_key":"cec-platform:2022:votetw-candidate-91cc0d4c61527aed","person_id":"4ddc1610-b831-4150-8577-bf8552cfd4e0","candidate_id":"713bc517-37e2-4fe4-b407-bed31ec86d68","name":"蔡依靜 Lamen．Panay","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC4-7%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"3e18152df0f2747ab2140e704cec47ead28ebe3095eae2f9ee5d1a4e70b7cbda","before_md5":"b75f10e82010ad3bbd0c2ba5098aeb00","after_text":"全心全力 守護部落\n專業監督 行政細節\n一、生活在安全的環境：重新檢視各部落生活條件，調查潛在危機區包括道路建設、擋土設施、溪流整治、環境汙染，事先勘查、統計，編列預算提早施作改善工程，預防災害發生，達到預防勝於治療的效果，保障部落基本生活品質。有地就要有路，爭取經費，鋪設產業道路，讓族人能充分發揮土地利用價值。\n二、定居在自己的土地：全力協助取得原住民保留地所有權狀，不要再讓族人空等待。監督國土計畫實施進度與執行細節，確保部落建物順利合法化，積極運用國土計畫工具，協助部落發展並新增部落住宅，讓返鄉定居心願成真。\n三、產業在文化中發展：不讓青年孤單奮戰，積極統合原住民部落青年創業資源，督促政府有效搭建原住民特色產業平台，提供六級化產業類別合作支援，提高部落青年經濟收益。\n四、文化在日常中傳承：督促政府盡速完成一部落一聚會所，同時串聯各項如文健站等軟體計劃，促使聚會所實質上成為部落文化中心，時時傳承部落文化。建立部落文化資料庫平台，提供部落青年田調口訪資源，累積耆老智慧，透過科技媒介克服空間障礙，成為新的傳承文化管道。爭取資源，擴大各部落各類型文化傳承工作。\n五、教育在時代中精進：擴大推動民族教育，讓wawa在文化脈絡中學習世界的知識，提高原住民學生教育獎學金，精進適性教育，鼓勵投入軍警、輔導國考擔任公教人員，穩定部落青年工作職業，提高部落在社會發聲的力量。\n不分黨派 全心問政 不分部落 全面服務","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["全心全力 守護部落 專業監督 行政細節","生活在安全的環境：重新檢視各部落生活條件，調查潛在危機區包括道路建設、擋土設施、溪流整治、環境汙染，事先勘查、統計，編列預算提早施作改善工程，預防災害發生，達到預防勝於治療的效果，保障部落基本生活品質。有地就要有路，爭取經費，鋪設產業道路，讓族人能充分發揮土地利用價值。","定居在自己的土地：全力協助取得原住民保留地所有權狀，不要再讓族人空等待。監督國土計畫實施進度與執行細節，確保部落建物順利合法化，積極運用國土計畫工具，協助部落發展並新增部落住宅，讓返鄉定居心願成真。","產業在文化中發展：不讓青年孤單奮戰，積極統合原住民部落青年創業資源，督促政府有效搭建原住民特色產業平台，提供六級化產業類別合作支援，提高部落青年經濟收益。","文化在日常中傳承：督促政府盡速完成一部落一聚會所，同時串聯各項如文健站等軟體計劃，促使聚會所實質上成為部落文化中心，時時傳承部落文化。建立部落文化資料庫平台，提供部落青年田調口訪資源，累積耆老智慧，透過科技媒介克服空間障礙，成為新的傳承文化管道。爭取資源，擴大各部落各類型文化傳承工作。","教育在時代中精進：擴大推動民族教育，讓wawa在文化脈絡中學習世界的知識，提高原住民學生教育獎學金，精進適性教育，鼓勵投入軍警、輔導國考擔任公教人員，穩定部落青年工作職業，提高部落在社會發聲的力量。 不分黨派 全心問政 不分部落 全面服務"]},{"id":"edba885b-a174-4add-8278-b68864a920df","claim_key":"cec-platform:2022:votetw-candidate-d3256e01bb779dea","person_id":"43e54291-13d7-4843-a833-7e406e0e32c6","candidate_id":"72dce79b-3c21-4783-bba0-2957d34e7031","name":"魏睿宏","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/17%E6%BE%8E%E6%B9%96%E7%B8%A3/%E6%BE%8E%E6%B9%96%E7%B8%A3%E7%AC%AC2%E3%80%813%E3%80%814%E3%80%815%E3%80%816%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"ee2c60825a1ff492417bf566a8540c7a787aa8859f0596610f4de010006aadbe","before_md5":"de289ef3e4628e499e2bf4c319db66fc","after_text":"1.健全澎湖縣緊急醫療救護作業系統，充實醫療基層人力，保障鄉親民眾生命安全。\n2.整修衛生所室場域，增購汰換老舊復健器材，滿足長者需求。\n3.爭取普設各鄉污水下水道工程，以維海洋潔淨，活化海洋資源，建構優質生活環境。\n4.協助反應漁民及漁業發展障礙與困難事項，維繫地方漁業永續發展。\n5.爭取漁港疏浚整治工作，並充實改善周邊漁具倉庫等港埠設施，符合漁民需求。\n6.全力推動地方特色農漁產品行銷，拓展市場銷售通路，開創活絡地方商機。\n7.加強推動觀光遊憩景點開發建設，結合文創產業，帶動地方整體發展。\n8.爭取社區活動中心汰舊換新經費。\n9.選擇公有地，營造親子活動遊憩設施環境，廣泛設置共融式公園。\n10.強化社會福利措施，照護弱勢族群。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["健全澎湖縣緊急醫療救護作業系統，充實醫療基層人力，保障鄉親民眾生命安全。","整修衛生所室場域，增購汰換老舊復健器材，滿足長者需求。","爭取普設各鄉污水下水道工程，以維海洋潔淨，活化海洋資源，建構優質生活環境。","協助反應漁民及漁業發展障礙與困難事項，維繫地方漁業永續發展。","爭取漁港疏浚整治工作，並充實改善周邊漁具倉庫等港埠設施，符合漁民需求。","全力推動地方特色農漁產品行銷，拓展市場銷售通路，開創活絡地方商機。","加強推動觀光遊憩景點開發建設，結合文創產業，帶動地方整體發展。","爭取社區活動中心汰舊換新經費。","選擇公有地，營造親子活動遊憩設施環境，廣泛設置共融式公園。","強化社會福利措施，照護弱勢族群。"]},{"id":"05416bad-b079-4a1c-b7c7-f41348bbe652","claim_key":"cec-platform:2022:votetw-candidate-a64836e0af5fcdc3","person_id":"bcd6e823-e94c-455a-9833-58722dc730c3","candidate_id":"7598233b-84f2-424f-8d50-2e170d05fe03","name":"宋昀芝","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/17%E6%BE%8E%E6%B9%96%E7%B8%A3/%E6%BE%8E%E6%B9%96%E7%B8%A3%E7%AC%AC2%E3%80%813%E3%80%814%E3%80%815%E3%80%816%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"ee2c60825a1ff492417bf566a8540c7a787aa8859f0596610f4de010006aadbe","before_md5":"e95d18386c3453575332a4eeaf79812e","after_text":"1.促進觀光文化新亮點\n2.提升就醫資源方便性\n3.重視老弱婦孺的權益\n4.爭取航道疏浚及漁港轉型\n5.以便民利民為服務主軸","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","reasonCodes":["heading_or_slogan"],"excludedItemCount":2}},"items":["促進觀光文化新亮點","提升就醫資源方便性","爭取航道疏浚及漁港轉型"]},{"id":"1bcdc483-919a-40fe-8617-55f42d8a2f94","claim_key":"cec-platform:2022:votetw-candidate-340d0d0b637d2138","person_id":"6c3e76a5-b4d9-42ef-8aac-9acb1317b809","candidate_id":"77df693f-26b2-472b-a0d1-9c3543fc639f","name":"吳傳地","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/07%E6%96%B0%E7%AB%B9%E7%B8%A3/%E6%96%B0%E7%AB%B9%E7%B8%A3%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"69576cd0a3ab504ac5d01e56cda7f1cbc1a7e1f2bc76b53f8d5cd276a2844116","before_md5":"dbaae5890f577badca4bdd94578e0cce","after_text":"一、督促縣府重視坡頭漁港船筏進出航道及港內定期清淤工程，紅毛港紅樹林至鳳坑漁港周邊工程進度控管及長期環境維護。\n二、持續爭取農委會農路改善工程，提升農產品運輸及進出安全。\n三、協助偏遠國中小教學環境改善，提升在地就學意願，縮小城鄉差距。\n四、督促縣府活化各國中小閒置空間，設置社區圖書室，提供在地學子假日閱讀使用。\n五、督促縣府加速「台一線替代道路，竹北—新豐段」新闢工程，以解決上下班壅塞情形。\n六、督促縣府解決大山崎地區就學問題（短期目標儘速完成松林國小擴建案，長期目標透過新設學校疏解山崎、松林等校學童活動空間不足問題）。\n七、爭取設立特色公園，並於公園改造同時評估設置地下停車空間，以解決都市計劃區內停車位不足問題。\n八、督促改善新豐火車站周邊髒亂問題，還給鄉民一個乾淨門面。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["督促縣府重視坡頭漁港船筏進出航道及港內定期清淤工程，紅毛港紅樹林至鳳坑漁港周邊工程進度控管及長期環境維護。","持續爭取農委會農路改善工程，提升農產品運輸及進出安全。","協助偏遠國中小教學環境改善，提升在地就學意願，縮小城鄉差距。","督促縣府活化各國中小閒置空間，設置社區圖書室，提供在地學子假日閱讀使用。","督促縣府加速「台一線替代道路，竹北—新豐段」新闢工程，以解決上下班壅塞情形。","督促縣府解決大山崎地區就學問題（短期目標儘速完成松林國小擴建案，長期目標透過新設學校疏解山崎、松林等校學童活動空間不足問題）。","爭取設立特色公園，並於公園改造同時評估設置地下停車空間，以解決都市計劃區內停車位不足問題。","督促改善新豐火車站周邊髒亂問題，還給鄉民一個乾淨門面。"]},{"id":"f060e7c8-5f45-4e2a-8da5-e599838f8321","claim_key":"cec-platform:2022:votetw-candidate-c20bb55a5067098f","person_id":"bf090d05-f8d7-4423-bd97-42a82324509a","candidate_id":"795c57f7-c4cc-4f02-97bc-716b2edce0a6","name":"陳雅倫","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC2%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"32edba7b81b8275dda1e15fb7f48a1771c8ae1bb8802e2bb6316cfa24cb26462","before_md5":"8d54a83aead33a76448cd2c50c1ddd6b","after_text":"一、【挺18公民權】\n世界上許多民主國家透過法律保障18歲青年享有公民權利及義務，台灣是亞洲首屈一指的民主國家，複決投下同意票支持18歲公民權修憲，完成世代平權，民主台灣再向前！\n二、【爭取婦幼福利】\n持續增加公托、共融式公園，並在龜山設置臨時托育中心，延長收托時間，要求增加托育人員待遇及爭取托育補助加碼。\n三、【投資教育環境】\n繼續監督大崗高中設校進度、持續督促文青國中小設校完成、爭取龜山新設圖書館、增加國際專班、推動學校雙語教學、本土語言課程及智慧教室數量。\n四、【改善交通路網】\n繼續監督捷運棕線實質進度、再增加龜山公車路網、完善候車系統、引進多元共享運具、設置交通寧靜區、繼續監督A7二期計畫道路打通進度。\n五、【提升長輩照顧】\n持續爭取龜山新設老人文康中心，擴充關懷據點功能，要求擴大敬老愛心卡使用範圍，照顧銀髮族好生活。\n六、【支持青年發展】\n繼續推動龜山設青創基地挺青年創業、爭取青年就業津貼加碼、持續監督龜山社會住宅興建、督促國民運動中心興建進度。\n七、【觀光休閒產業】\n將虎頭山風景特定區、楓茶米休閒農業區、龜山苗圃露營區、桃林鐵道、南崁溪自行車道整合成《大桃園生態都會公園》，吸引人潮前來龜山消費，振興市場活絡地方經濟；推動大棟山風景特定區核定將歷史與人文故事融入周邊商圈創造地方繁榮。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["【挺18公民權】 世界上許多民主國家透過法律保障18歲青年享有公民權利及義務，台灣是亞洲首屈一指的民主國家，複決投下同意票支持18歲公民權修憲，完成世代平權，民主台灣再向前！","【爭取婦幼福利】 持續增加公托、共融式公園，並在龜山設置臨時托育中心，延長收托時間，要求增加托育人員待遇及爭取托育補助加碼。","【投資教育環境】 繼續監督大崗高中設校進度、持續督促文青國中小設校完成、爭取龜山新設圖書館、增加國際專班、推動學校雙語教學、本土語言課程及智慧教室數量。","【改善交通路網】 繼續監督捷運棕線實質進度、再增加龜山公車路網、完善候車系統、引進多元共享運具、設置交通寧靜區、繼續監督A7二期計畫道路打通進度。","【提升長輩照顧】 持續爭取龜山新設老人文康中心，擴充關懷據點功能，要求擴大敬老愛心卡使用範圍，照顧銀髮族好生活。","【支持青年發展】 繼續推動龜山設青創基地挺青年創業、爭取青年就業津貼加碼、持續監督龜山社會住宅興建、督促國民運動中心興建進度。","【觀光休閒產業】 將虎頭山風景特定區、楓茶米休閒農業區、龜山苗圃露營區、桃林鐵道、南崁溪自行車道整合成《大桃園生態都會公園》，吸引人潮前來龜山消費，振興市場活絡地方經濟；推動大棟山風景特定區核定將歷史與人文故事融入周邊商圈創造地方繁榮。"]},{"id":"af6aa675-4808-4df4-84e6-9edf58d0dcf7","claim_key":"cec-platform:2022:votetw-candidate-7896a9fe8c4af741","person_id":"292b4b97-1373-425e-a764-94ea1c9562b7","candidate_id":"874bf11d-5741-4e4a-a38c-7b818e4ff349","name":"陳佩真","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/17%E6%BE%8E%E6%B9%96%E7%B8%A3/%E6%BE%8E%E6%B9%96%E7%B8%A3%E7%AC%AC2%E3%80%813%E3%80%814%E3%80%815%E3%80%816%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"ee2c60825a1ff492417bf566a8540c7a787aa8859f0596610f4de010006aadbe","before_md5":"de289ef3e4628e499e2bf4c319db66fc","after_text":"一、爭取加強在籍鄉民搭乘交通船補助\n二、加強爭取各村補網場及漁具倉庫興建\n三、爭取加強各村老舊社區活動中心及鄉內老舊道路改善\n四、爭取學生教育軟硬體各項補助\n五、爭取各漁港持續疏濬及各碼頭改善\n六、爭取各村入口意象，促進地方觀光發展\n七、籲請政府在觀光、環保與漁業發展取得平衡點，捍衛漁民生存權\n八、爭取加強解決三級離島水（海淡廠興建）、電（各村平均3台發電機）定期航線交通問題（馬公↔花嶼），（馬公↔南方四島）\n九、建請政府增加社會福利，照顧偏鄉民眾。\n十、主張縣府督促海管處六大承諾應予實現，不能失信於民。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["爭取加強在籍鄉民搭乘交通船補助","加強爭取各村補網場及漁具倉庫興建","爭取加強各村老舊社區活動中心及鄉內老舊道路改善","爭取學生教育軟硬體各項補助","爭取各漁港持續疏濬及各碼頭改善","爭取各村入口意象，促進地方觀光發展","籲請政府在觀光、環保與漁業發展取得平衡點，捍衛漁民生存權","爭取加強解決三級離島水（海淡廠興建）、電（各村平均3台發電機）定期航線交通問題（馬公↔花嶼），（馬公↔南方四島）","建請政府增加社會福利，照顧偏鄉民眾。","主張縣府督促海管處六大承諾應予實現，不能失信於民。"]},{"id":"322f85d2-dbb5-4ea3-a897-cc9a5b798530","claim_key":"cec-platform:2022:votetw-candidate-077e1c714182b2b7","person_id":"ca4899fc-e9d8-438b-b253-187f108775f4","candidate_id":"887764d5-cff2-47b2-8509-a41b12ea4b9c","name":"胡松榮","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/17%E6%BE%8E%E6%B9%96%E7%B8%A3/%E6%BE%8E%E6%B9%96%E7%B8%A3%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"c9aaaf6c72d2713702c0c6972ecd2623433b8ae7f029e561144dca9cba9877d8","before_md5":"49a0bd5ff3c9b5821070a2ca6de3b33d","after_text":"一、充實澎湖體育硬體設施，推廣全民運動，培育優秀體育人才。\n二、關注澎湖教育、文化水平，提昇子弟競爭力。\n三、督促縣府正視澎湖醫療、交通困境，研提有效因應方案，增進澎湖縣民福祉，達成幸福城市目標。\n四、促請縣府規劃馬公市、澎南區觀光動線，帶動澎南區經濟活絡。\n五、督促縣府嚴密控管澎防部、團管區外遷作業期程，俾利馬公市區活絡繁榮。\n六、積極爭取中央經費，以斜張橋方式改建澎湖跨海大橋。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","reasonCodes":["heading_or_slogan"],"excludedItemCount":1}},"items":["充實澎湖體育硬體設施，推廣全民運動，培育優秀體育人才。","督促縣府正視澎湖醫療、交通困境，研提有效因應方案，增進澎湖縣民福祉，達成幸福城市目標。","促請縣府規劃馬公市、澎南區觀光動線，帶動澎南區經濟活絡。","督促縣府嚴密控管澎防部、團管區外遷作業期程，俾利馬公市區活絡繁榮。","積極爭取中央經費，以斜張橋方式改建澎湖跨海大橋。"]},{"id":"4a099606-545a-4554-a9e2-a806b043b678","claim_key":"cec-platform:2022:votetw-candidate-a5f2aa7b1e5946d7","person_id":"39463f8d-f75e-4beb-92a5-bc861c8d8877","candidate_id":"8cd65a6d-6da5-437e-8221-d365a9559e64","name":"張再興","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/17%E6%BE%8E%E6%B9%96%E7%B8%A3/%E6%BE%8E%E6%B9%96%E7%B8%A3%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"c9aaaf6c72d2713702c0c6972ecd2623433b8ae7f029e561144dca9cba9877d8","before_md5":"c359f5ad5f305be92293b0cac4baf361","after_text":"一、促進馬公港建設，成為免稅島振興經濟\n二、建議增加駐軍刺激消費","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["促進馬公港建設，成為免稅島振興經濟","建議增加駐軍刺激消費"]},{"id":"b1ec7be6-9cda-4b61-be69-7e664fa2184c","claim_key":"cec-platform:2022:votetw-candidate-4202d7e44171e0ef","person_id":"e16fd503-47e3-44dc-a43a-259f0cfd1fa8","candidate_id":"950c7e15-fd35-421d-8511-7865819ccc02","name":"王景山","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/13%E5%B1%8F%E6%9D%B1%E7%B8%A3/%E5%B1%8F%E6%9D%B1%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"132b3a73cbb10441e2b62d9316fb1831db862536766e14ea378abb1df4663ad1","before_md5":"65f09b5490e54a7352a408f1fe55ad15","after_text":"王景山持續尚骨力服務\n持續爭取經費，興建及修繕道路及公共設施，提升居住生活品質。\n持續爭取經費改善及修繕農水路和灌溉設施，落實重視土地，照顧農民權益。\n持續爭取路燈全面更換為環保節能的LED路燈，透過無線故障回傳通報功能縮短維修時間，讓「夜晚回家的路明亮安全」。\n爭取設立農漁產平台，輔導農民申請認證，建立特色品牌，提高農民收益。\n爭取設立冷鏈物流園區，提升溫控貯存運輸能力，確保農產品質，減少農民損失。\n善用科技，導入智慧農業，吸引年輕人返鄉投入農業、行銷屏東農產品。\n爭取提高農保喪葬津貼，讓農民得到最後的尊嚴，也減輕身後其家屬經濟負擔。\n爭取調整農業保險的理賠條件，提高農民投保意願，分散種植風險。\n爭取補助中小學生營養午餐費，並採用在地食材，一周一日有機蔬菜，從產地到餐桌建立食安鏈，讓孩子健康成長。\n爭取設置網路教學系統，並補助偏鄉小學購置平板電腦，充分運用網路以及新科技教學，弭平城鄉差距。\n爭取設立新住民服務中心及關懷據點，不僅讓新住民姊妹有專屬空間可以相聚，更可提供法律、福利、就業等協助。\n爭取提高社會福利預算，提高對單親家庭、身障人士、新住民等弱勢家庭的照護品質。\n督促政府加強防疫清消，並加強宣導注射疫苗。","split":{"method":"line","version":"election-content-items-v1","confidence":85,"reviewStatus":"auto_approved"},"items":["王景山持續尚骨力服務：持續爭取經費，興建及修繕道路及公共設施，提升居住生活品質。","王景山持續尚骨力服務：持續爭取經費改善及修繕農水路和灌溉設施，落實重視土地，照顧農民權益。","王景山持續尚骨力服務：持續爭取路燈全面更換為環保節能的LED路燈，透過無線故障回傳通報功能縮短維修時間，讓「夜晚回家的路明亮安全」。","王景山持續尚骨力服務：爭取設立農漁產平台，輔導農民申請認證，建立特色品牌，提高農民收益。","王景山持續尚骨力服務：爭取設立冷鏈物流園區，提升溫控貯存運輸能力，確保農產品質，減少農民損失。","王景山持續尚骨力服務：善用科技，導入智慧農業，吸引年輕人返鄉投入農業、行銷屏東農產品。","王景山持續尚骨力服務：爭取提高農保喪葬津貼，讓農民得到最後的尊嚴，也減輕身後其家屬經濟負擔。","王景山持續尚骨力服務：爭取調整農業保險的理賠條件，提高農民投保意願，分散種植風險。","王景山持續尚骨力服務：爭取補助中小學生營養午餐費，並採用在地食材，一周一日有機蔬菜，從產地到餐桌建立食安鏈，讓孩子健康成長。","王景山持續尚骨力服務：爭取設置網路教學系統，並補助偏鄉小學購置平板電腦，充分運用網路以及新科技教學，弭平城鄉差距。","王景山持續尚骨力服務：爭取設立新住民服務中心及關懷據點，不僅讓新住民姊妹有專屬空間可以相聚，更可提供法律、福利、就業等協助。","王景山持續尚骨力服務：爭取提高社會福利預算，提高對單親家庭、身障人士、新住民等弱勢家庭的照護品質。","王景山持續尚骨力服務：督促政府加強防疫清消，並加強宣導注射疫苗。"]},{"id":"0ade5653-06ae-4c4f-a3eb-ef8c33fc74b2","claim_key":"cec-platform:2022:votetw-candidate-2b48ab006af99455","person_id":"0c41448d-04d9-4233-988c-77e1251077a4","candidate_id":"9ecae5da-7dc2-47a5-a2b6-8f612171ea6f","name":"方文正","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/13%E5%B1%8F%E6%9D%B1%E7%B8%A3/%E5%B1%8F%E6%9D%B1%E7%B8%A3%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"c4ec4b59e24163526e3504f3d7b798532fafa689f63bcb9ab9e35628d7665151","before_md5":"89812bd7e9baf5f8a3e184843c86b534","after_text":"1.配合縣府繼續爭取高雄捷運延伸到新園、東港，延續上屆未竟政見。\n2.爭取加速新園鄉鹽埔漁港、漁業遊憩、觀光綜合開發計劃。\n3.協助農漁民建立生產履歷，產官學通力合作，打開行銷通路，增加農漁民收益。\n4.爭取利用東港共和新村用地成立「青創園區」。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["配合縣府繼續爭取高雄捷運延伸到新園、東港，延續上屆未竟政見。","爭取加速新園鄉鹽埔漁港、漁業遊憩、觀光綜合開發計劃。","協助農漁民建立生產履歷，產官學通力合作，打開行銷通路，增加農漁民收益。","爭取利用東港共和新村用地成立「青創園區」。"]},{"id":"31f508ad-ea0b-4351-a937-18680b155aeb","claim_key":"cec-platform:2022:votetw-candidate-6965e2cdbe7b51e2","person_id":"77968eeb-995f-447f-85e3-d04a290f4e35","candidate_id":"9f676ab3-f602-4620-8847-18b9681d8318","name":"范織欽 Pasulang．Tomatalate","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC12.13.14.15%E9%81%B8%E5%8D%80.pdf","source_sha256":"ba9a3887bee3f731b69f8a20cab45fd79dd216a3636e5e8b3ca7ba04a7411766","before_md5":"ed081d8972a501edd416e0284c3b9c06","after_text":"1. 督促市政府釋出閒置空間建築物，作為原住民文健站及社團辦公據點。\n2. 督促市政府重視原住民弱勢家庭扶助，鬆綁相關法規，落實公私資源整合。\n3. 督促市政府重視與協助原住民教會推動社會公益活動，減少犯罪行為之發生。\n4. 督促市警局重視原住民警消人員工作升遷之保障，並且確實發放重點加給津貼，符合公平正義。\n5. 督促市政府增編農路維修預算，暢通農產運輸要道，方便農產運銷。\n6. 督促市政府結合茂林風景區管理處之行政資源，推展原鄉觀光產業發展，增進原鄉居民經濟收入。\n7. 督促市政府重視原住民文化教材之編撰，提供教師教學及學生自學之資料庫。\n8. 督促市政府興建專屬原住民社會住宅，保障都會區原住民家庭居住正義。\n9. 建置都會區原住民健康大數據，預防疾病、延長壽命與增進健康之作為。\n10. 督促市政府盤點高雄S廊帶半導體產業園區所需人力，主動媒合產業與學校養成教育，促進原住民青年學子落地就業機會。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["督促市政府釋出閒置空間建築物，作為原住民文健站及社團辦公據點。","督促市政府重視原住民弱勢家庭扶助，鬆綁相關法規，落實公私資源整合。","督促市政府重視與協助原住民教會推動社會公益活動，減少犯罪行為之發生。","督促市警局重視原住民警消人員工作升遷之保障，並且確實發放重點加給津貼，符合公平正義。","督促市政府增編農路維修預算，暢通農產運輸要道，方便農產運銷。","督促市政府結合茂林風景區管理處之行政資源，推展原鄉觀光產業發展，增進原鄉居民經濟收入。","督促市政府重視原住民文化教材之編撰，提供教師教學及學生自學之資料庫。","督促市政府興建專屬原住民社會住宅，保障都會區原住民家庭居住正義。","建置都會區原住民健康大數據，預防疾病、延長壽命與增進健康之作為。","督促市政府盤點高雄S廊帶半導體產業園區所需人力，主動媒合產業與學校養成教育，促進原住民青年學子落地就業機會。"]},{"id":"b852c88a-d6d8-4f36-bd3d-1ef79b5328e3","claim_key":"cec-platform:2022:votetw-candidate-78bcd41e838fe3e4","person_id":"06e1a514-8df8-4782-bad7-75252931ea67","candidate_id":"ad84ce01-3a21-4837-8a3a-d6f83f45ee5a","name":"呂黃春金","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/17%E6%BE%8E%E6%B9%96%E7%B8%A3/%E6%BE%8E%E6%B9%96%E7%B8%A3%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"c9aaaf6c72d2713702c0c6972ecd2623433b8ae7f029e561144dca9cba9877d8","before_md5":"e2da0c65a2c5405961f065f12dac1906","after_text":"一、嚴格把關政府預算編列及執行\n二、爭取社區高齡友善軟硬體服務配套\n三、重視海洋保育問題永續漁業\n四、要求縣府發展主題觀光振興秋冬旅遊市場\n五、爭取幼兒照顧及青年創業補助","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","reasonCodes":["heading_or_slogan"],"excludedItemCount":1}},"items":["嚴格把關政府預算編列及執行","爭取社區高齡友善軟硬體服務配套","要求縣府發展主題觀光振興秋冬旅遊市場","爭取幼兒照顧及青年創業補助"]},{"id":"6b05daf9-5689-42d7-ad15-f21ef8493c1c","claim_key":"cec-platform:2022:votetw-candidate-b2c0474a07a00895","person_id":"42faaaa2-bb4e-4519-afbe-ab4295aa721a","candidate_id":"aea3cea4-7a5a-4534-be75-221c2ff21128","name":"周典論","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/13%E5%B1%8F%E6%9D%B1%E7%B8%A3/%E5%B1%8F%E6%9D%B1%E7%B8%A3%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"c4ec4b59e24163526e3504f3d7b798532fafa689f63bcb9ab9e35628d7665151","before_md5":"49682cd556a52cf885427feed99cb342","after_text":"一、爭取基層建設，改善鄉親生活\n二、重視教育發展，扶助弱勢學生\n三、引進科技產業，增加就業機會\n四、發展休閒觀光，活絡地方經濟\n五、農漁產業升級，增加農漁民收入\n六、關心新住民生活，尊重多元文化","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","reasonCodes":["heading_or_slogan"],"excludedItemCount":1}},"items":["爭取基層建設，改善鄉親生活","重視教育發展，扶助弱勢學生","引進科技產業，增加就業機會","發展休閒觀光，活絡地方經濟","農漁產業升級，增加農漁民收入"]},{"id":"1142f577-a843-4dda-a47b-6039808f2490","claim_key":"cec-platform:2022:votetw-candidate-f186bec640886a1f","person_id":"9566e381-d077-40f5-9ab7-4e229120ae75","candidate_id":"b1b84e91-f9f8-4611-b20c-ba7935d49040","name":"盧文瑞","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/13%E5%B1%8F%E6%9D%B1%E7%B8%A3/%E5%B1%8F%E6%9D%B1%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"132b3a73cbb10441e2b62d9316fb1831db862536766e14ea378abb1df4663ad1","before_md5":"61da208bcda7e823a34180485926499b","after_text":"一、高屏溪河川公地養殖合法化有條件開放，輔導魚塭養殖業者取得圍築魚塭使用許可。\n二、易淹水地區水患治理計畫「武洛溪排水系統」引進武洛溪之水源為高屏溪支流隘寮溪之入滲伏流水，搭配地表水淨化的運用，可形成「地表水與地下水聯合運用模式」。\n三、高樹及里港地區砂石車專用道建設計畫－「拓寬載興村至里崇路廢鐵道銜接台3線及台22線」施作基礎改建及擴建，拓寬之行車路線為現行砂石運輸業者習慣行經之路線。規劃將現有廢鐵道8米道路拓寬為20米道路，向西南由出里港市區外之台3線接往國道3號，向西由台22線接國道10號。得以紓解高樹鹽埔地區砂石運輸業者交通運量。\n四、期盼建構屏北地區直捷聯繫路網，新闢國10里港至新威大橋道路。\n五、維護本縣天然資源降低衝擊地方景觀，爭取土石採取景觀維護特別稅回饋造福地方。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["高屏溪河川公地養殖合法化有條件開放，輔導魚塭養殖業者取得圍築魚塭使用許可。","易淹水地區水患治理計畫「武洛溪排水系統」引進武洛溪之水源為高屏溪支流隘寮溪之入滲伏流水，搭配地表水淨化的運用，可形成「地表水與地下水聯合運用模式」。","高樹及里港地區砂石車專用道建設計畫－「拓寬載興村至里崇路廢鐵道銜接台3線及台22線」施作基礎改建及擴建，拓寬之行車路線為現行砂石運輸業者習慣行經之路線。規劃將現有廢鐵道8米道路拓寬為20米道路，向西南由出里港市區外之台3線接往國道3號，向西由台22線接國道10號。得以紓解高樹鹽埔地區砂石運輸業者交通運量。","期盼建構屏北地區直捷聯繫路網，新闢國10里港至新威大橋道路。","維護本縣天然資源降低衝擊地方景觀，爭取土石採取景觀維護特別稅回饋造福地方。"]},{"id":"08278386-d6ca-4fbd-bf2e-ad2d62e2b363","claim_key":"cec-platform:2022:votetw-candidate-5d2c77e063c98797","person_id":"9df321f9-ffbb-4123-9a57-26f0e18cf4c7","candidate_id":"b5a5e4f4-47b4-422e-a859-c48d16dbeeef","name":"游吉祥","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/14%E5%AE%9C%E8%98%AD%E7%B8%A3/%E5%AE%9C%E8%98%AD%E7%B8%A3%E7%AC%AC13%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"0ba7cc62cde87da0c70890def6efef6969d165783b6a3361f45082a80c9f561e","before_md5":"5924d9d1f16cda52fd095bf14fc506ba","after_text":"「理性問政，專業堅持；清廉熱忱，族人第一；為您做事，我的榮幸。」\n1. 強化原住民主體性，落實推動原住民政策主流化。\n2. 監督縣政，強調公開、透明、效率與品質，以落實原鄉各項公共政策之目標。\n3. 爭取中央與縣府經費，改善部落基礎建設，營造友善環境，保障族人基本生活品質。\n4. 活用大南澳地區獨特的山、河、海自然環境及原、客、閩的多元文化特色，結合地方創生計畫，發展農、漁、林、休閒運動、文化體驗及生態旅遊等多元產業，優化原鄉產業經濟，並積極培力在地人才，延攬青年回鄉，吸引企業進駐，活力部落，永續原鄉。\n5. 重視社會福利政策，落實長者照護及弱勢關懷，保障族人生活品質，照護原鄉、守護生命。\n6. 提升全鄉醫療品質，推動遠距醫療服務，善用科技補足人力，營造醫療平權、就醫無礙、如醫到府的友善健康環境。\n7. 強化國土計畫法，重視原鄉區域計畫，捍衛族人居住正義，保障族人生存權。\n8. 充實原鄉學校軟硬體設施，建構優質的學習環境，提升教師專業發展，激發學生多元智慧，落實教育目標。\n9. 積極推動民族教育，發展民族教育課程方案與內容，建構民族教育知識系統，落實民族教育完整學習體制之目標。\n10. 積極協助推動蘇花安－東澳至南澳段廊道計畫，提供族人一條安全舒適的道路。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["「理性問政，專業堅持；清廉熱忱，族人第一；為您做事，我的榮幸。」","強化原住民主體性，落實推動原住民政策主流化。","監督縣政，強調公開、透明、效率與品質，以落實原鄉各項公共政策之目標。","爭取中央與縣府經費，改善部落基礎建設，營造友善環境，保障族人基本生活品質。","活用大南澳地區獨特的山、河、海自然環境及原、客、閩的多元文化特色，結合地方創生計畫，發展農、漁、林、休閒運動、文化體驗及生態旅遊等多元產業，優化原鄉產業經濟，並積極培力在地人才，延攬青年回鄉，吸引企業進駐，活力部落，永續原鄉。","重視社會福利政策，落實長者照護及弱勢關懷，保障族人生活品質，照護原鄉、守護生命。","提升全鄉醫療品質，推動遠距醫療服務，善用科技補足人力，營造醫療平權、就醫無礙、如醫到府的友善健康環境。","強化國土計畫法，重視原鄉區域計畫，捍衛族人居住正義，保障族人生存權。","充實原鄉學校軟硬體設施，建構優質的學習環境，提升教師專業發展，激發學生多元智慧，落實教育目標。","積極推動民族教育，發展民族教育課程方案與內容，建構民族教育知識系統，落實民族教育完整學習體制之目標。","積極協助推動蘇花安－東澳至南澳段廊道計畫，提供族人一條安全舒適的道路。"]},{"id":"457eb47c-6faa-4deb-bb3d-a95e129a6f5e","claim_key":"cec-platform:2022:votetw-candidate-a566cb002a331462","person_id":"4aed9c1e-dd18-4429-9354-20f26b776cae","candidate_id":"bf56f6e8-d5ee-43d7-8f0c-20c86077721c","name":"蘇育德","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/17%E6%BE%8E%E6%B9%96%E7%B8%A3/%E6%BE%8E%E6%B9%96%E7%B8%A3%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"c9aaaf6c72d2713702c0c6972ecd2623433b8ae7f029e561144dca9cba9877d8","before_md5":"36e0a07c2ee8e3e4619e74d3df3c2c1d","after_text":"感謝鄉親給予育德八年基層歷練的機會，如今已準備好，為鄉親服務更多。以下是我未來進入議會要與縣政府共同努力的願景：\n01.貫徹無障礙：督促政府落實公共設施無障礙動線。\n02.滿足親子遊憩空間需求，爭取政府規劃遮風避雨的孩子放電場所。\n03.檢討閒置空間、推動實驗劇場與live house、擬定青創協力方案。\n04.媒合資源，推動藝文團隊冬季軟實力培訓方案。\n05.維護行人通行權與檢討禁行機車道等交通問題。\n06.從公部門落實友善品牌：多國語言服務、生理友善服務、行動裝置即時充電服務。\n07.鄉市托、國小附幼、準公幼與公托資源整合，全力滿足托育、幼教需求。\n08.提升大眾運輸便利性，票務e化，並檢討班次，更符合使用者需求。\n09.力推流浪動物絕育，取締未打晶片飼主及非法放養，減少動物與民眾衝突問題。\n10.確保外聘或計畫聘用之治療師、社工、專業臨時人員，不因行政程序而遭積欠薪資。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","reasonCodes":["heading_or_slogan"],"excludedItemCount":1}},"items":["貫徹無障礙：督促政府落實公共設施無障礙動線。","滿足親子遊憩空間需求，爭取政府規劃遮風避雨的孩子放電場所。","檢討閒置空間、推動實驗劇場與live house、擬定青創協力方案。","媒合資源，推動藝文團隊冬季軟實力培訓方案。","維護行人通行權與檢討禁行機車道等交通問題。","從公部門落實友善品牌：多國語言服務、生理友善服務、行動裝置即時充電服務。","鄉市托、國小附幼、準公幼與公托資源整合，全力滿足托育、幼教需求。","提升大眾運輸便利性，票務e化，並檢討班次，更符合使用者需求。","力推流浪動物絕育，取締未打晶片飼主及非法放養，減少動物與民眾衝突問題。","確保外聘或計畫聘用之治療師、社工、專業臨時人員，不因行政程序而遭積欠薪資。"]},{"id":"f22513c8-9a1b-4ba0-8a74-582c4dcf14ae","claim_key":"cec-platform:2022:votetw-candidate-e516c6422c200d9f","person_id":"5d5c1898-d4ba-48d5-b594-fc53454666dc","candidate_id":"c89097a1-b093-4f1e-b80e-0e32a4bc7030","name":"黃家齊","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"f9177929bf172a53a6f7d38630f1c19c985b304bd020f4eb6e88174b52f1a9db","before_md5":"1947055256b90a2eeac98370d238794b","after_text":"◆都市發展：\n1. 提高危老獎勵：容積獎勵、費用補助、貸款和利息補貼、稅務減免。\n2. 提升活動中心使用透明性：優質集會空間，促進區里平衡發展。鄰里作業調整，深化基層服務功能。\n3. 社會住宅餘域空間，設置微型運動中心。\n◆交通建設：\n1. 推動人工智慧AI號誌控制、智慧交通控制偵測、智慧交通安全路口防護計畫，並使科技執法全面化。\n2. 中平路銜接國道二號新匝道工程，紓解南桃園交流道阻塞壓力。\n3. 公共空間規劃電動車充電設施及充電環境。\n◆環境保護：\n1. 南崁溪大埔橋上游及東門溪氨氮削減設施，降低氨氮汙染量，加速改善南崁溪流域水質。\n2. 加強遊蕩動物管制措施，執行TNVR，改善攻追行為。\n◆社會福利：\n1. 擴大復康巴士量能，保障行動不便者行的權利。\n2. 增設安家食物銀行，提供弱勢家庭民生物資。\n3. 推動托育公共化政策。\n◆關心教育：\n1. 提升校園設備，建置校園安全防線。\n2. 改善校園男女廁所比例，增設性別友善廁所。\n3. 推動雙語學校計畫，提升外師涵蓋率。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","reasonCodes":["heading_or_slogan"],"excludedItemCount":1}},"items":["都市發展：提高危老獎勵：容積獎勵、費用補助、貸款和利息補貼、稅務減免。","都市發展：提升活動中心使用透明性：優質集會空間，促進區里平衡發展。鄰里作業調整，深化基層服務功能。","都市發展：社會住宅餘域空間，設置微型運動中心。","交通建設：推動人工智慧AI號誌控制、智慧交通控制偵測、智慧交通安全路口防護計畫，並使科技執法全面化。","交通建設：中平路銜接國道二號新匝道工程，紓解南桃園交流道阻塞壓力。","交通建設：公共空間規劃電動車充電設施及充電環境。","交通建設：南崁溪大埔橋上游及東門溪氨氮削減設施，降低氨氮汙染量，加速改善南崁溪流域水質。","交通建設：加強遊蕩動物管制措施，執行TNVR，改善攻追行為。","社會福利：擴大復康巴士量能，保障行動不便者行的權利。","社會福利：增設安家食物銀行，提供弱勢家庭民生物資。","社會福利：推動托育公共化政策。","關心教育：提升校園設備，建置校園安全防線。","關心教育：改善校園男女廁所比例，增設性別友善廁所。","關心教育：推動雙語學校計畫，提升外師涵蓋率。"]},{"id":"97f8e0fd-f912-4b2b-8e0c-0f54e5d11a3f","claim_key":"cec-platform:2022:votetw-candidate-0a9dcb62cc36caf2","person_id":"47e14385-7e97-4e24-b817-662b3e571e65","candidate_id":"c9b7be94-dc4f-4adb-affd-d73c8411c3c6","name":"李紀財 Mulaneng Paliuliu","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/13%E5%B1%8F%E6%9D%B1%E7%B8%A3/%E5%B1%8F%E6%9D%B1%E7%B8%A3%E7%AC%AC8%E3%80%8113-16%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"524f9657b4af1b226a4926022ada959412ea2880d9650209ddd4123156215480","before_md5":"ae2576337f5a553dad593e7c569a70d9","after_text":"1.以感恩的心，尊重宗教信仰，營造和善環境。\n2.持續爭取軟硬體建設，增進地方發展。\n3.持續爭取獅頭山開發為綜合發展中心。\n4.持續爭取原住民土地、文化轉型正義，還我族人尊嚴及權益。\n5.持續爭取部落文健站、關懷站、課輔班環境改善。\n6.全力配合協助公部門、各村、社區、學校、教會、青年會推動各項發展。\n7.持續爭取鄉內河川疏浚、野溪整治以維護鄉民權益及財產安全。\n8.持續爭取農產行銷及價格穩定，增加農業資材補助數量及金額。\n9.持續推動電力公司變電所、國防部射擊場遷移案及敦親睦鄰工作。\n10.聯合屏南地區民意代表、鄉鎮公所、議員爭取建設屏南快速道路及輕軌觀光火車以解決交通問題，增進觀光發展。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","reasonCodes":["heading_or_slogan"],"excludedItemCount":1}},"items":["持續爭取軟硬體建設，增進地方發展。","持續爭取獅頭山開發為綜合發展中心。","持續爭取原住民土地、文化轉型正義，還我族人尊嚴及權益。","持續爭取部落文健站、關懷站、課輔班環境改善。","全力配合協助公部門、各村、社區、學校、教會、青年會推動各項發展。","持續爭取鄉內河川疏浚、野溪整治以維護鄉民權益及財產安全。","持續爭取農產行銷及價格穩定，增加農業資材補助數量及金額。","持續推動電力公司變電所、國防部射擊場遷移案及敦親睦鄰工作。","聯合屏南地區民意代表、鄉鎮公所、議員爭取建設屏南快速道路及輕軌觀光火車以解決交通問題，增進觀光發展。"]},{"id":"ac787c39-9171-40a5-9611-0a9f90496a97","claim_key":"cec-platform:2022:votetw-candidate-1ca8e8d35ae633b0","person_id":"c9881864-4a18-41af-ba59-94e0db19b54a","candidate_id":"ca823a53-97a8-4dbb-9b3b-69573d0dde71","name":"葉明博","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/13%E5%B1%8F%E6%9D%B1%E7%B8%A3/%E5%B1%8F%E6%9D%B1%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"132b3a73cbb10441e2b62d9316fb1831db862536766e14ea378abb1df4663ad1","before_md5":"ddd7906361feaad7ca90764005c5146d","after_text":"1.嚴格監督提昇縣府行政、預算、社福、建設之功能效率。\n2.輔導農業轉型升級，設立農產品專業特區，並健全運銷制度，減少中間剝削，提高農民收益。\n3.推動農地改良輔助方案，降低農藥使用，提高農產品產量。\n4.地方觀光資源開發，改善交通網及屏縣重南輕北之落差。\n5.建立鄉鎮就業資訊服務網站，提高鄉民就業機會。\n6.促成台糖土地開發利用，增加地方稅收及居民就業機會。\n7.推動公辦民營安養中心，健全老人安養功能照顧。\n8.加強六歲以下幼兒照顧，規劃幼兒及醫療補助方案。\n9.尊重女權，保障婦女工作權益，落實兩性平等理念。\n10.推動校園社區化，提供休閒場所，提高社區藝文水準。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["嚴格監督提昇縣府行政、預算、社福、建設之功能效率。","輔導農業轉型升級，設立農產品專業特區，並健全運銷制度，減少中間剝削，提高農民收益。","推動農地改良輔助方案，降低農藥使用，提高農產品產量。","地方觀光資源開發，改善交通網及屏縣重南輕北之落差。","建立鄉鎮就業資訊服務網站，提高鄉民就業機會。","促成台糖土地開發利用，增加地方稅收及居民就業機會。","推動公辦民營安養中心，健全老人安養功能照顧。","加強六歲以下幼兒照顧，規劃幼兒及醫療補助方案。","尊重女權，保障婦女工作權益，落實兩性平等理念。","推動校園社區化，提供休閒場所，提高社區藝文水準。"]},{"id":"3ae78410-1478-432f-8897-1b372b315397","claim_key":"cec-platform:2022:votetw-candidate-e9819dc70eff0836","person_id":"2e721e75-d403-4ce6-bbd1-f2172484156e","candidate_id":"ccf4701d-ad1b-4d18-9f3b-f6dce09b6175","name":"許國政","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/17%E6%BE%8E%E6%B9%96%E7%B8%A3/%E6%BE%8E%E6%B9%96%E7%B8%A3%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"c9aaaf6c72d2713702c0c6972ecd2623433b8ae7f029e561144dca9cba9877d8","before_md5":"d2ce73dc315d6539fd95f7ae7797fbe6","after_text":"一、用心服務選民：二十年的專業問政，一輩子的用心服務。\n二、公務警消福利：爭取發放三節慰問金，提高警消勤務加給津貼、健檢補助金額及放寬補助年齡。\n三、友善幼托環境：擴大育兒津貼，推動托育公共及準公共化，力求幼教資源均衡分配。\n四、鼓勵青年留鄉：地方產業創意產品人才培育，獎勵年輕人留鄉創業，一起為澎湖打拚。\n五、幸福高齡社區：持續推動長者共餐及在地安養，營塑溫暖幸福快樂銀髮族社區。\n六、推動旅遊市場：設立市區觀光市場，推動文創農漁市集，打造澎南線等旅遊動線特色品牌。\n七、新住民文化融合：運用閒置空間，成立新住民交流學習中心，促進社會多元文化融合發展。\n八、活化市區土地：力促澎防部及後指部外遷，串連市區觀光漫遊動線，打造澎湖旅遊新亮點。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["用心服務選民：二十年的專業問政，一輩子的用心服務。","公務警消福利：爭取發放三節慰問金，提高警消勤務加給津貼、健檢補助金額及放寬補助年齡。","友善幼托環境：擴大育兒津貼，推動托育公共及準公共化，力求幼教資源均衡分配。","鼓勵青年留鄉：地方產業創意產品人才培育，獎勵年輕人留鄉創業，一起為澎湖打拚。","幸福高齡社區：持續推動長者共餐及在地安養，營塑溫暖幸福快樂銀髮族社區。","推動旅遊市場：設立市區觀光市場，推動文創農漁市集，打造澎南線等旅遊動線特色品牌。","新住民文化融合：運用閒置空間，成立新住民交流學習中心，促進社會多元文化融合發展。","活化市區土地：力促澎防部及後指部外遷，串連市區觀光漫遊動線，打造澎湖旅遊新亮點。"]},{"id":"7efae8f4-a1c1-404e-8e8d-8f1083570e74","claim_key":"cec-platform:2022:votetw-candidate-99175bafd6d8343c","person_id":"ecd91abc-3fdc-4369-afc0-a3ba1b4b1eff","candidate_id":"cf54d3b1-8335-4ed5-8c4a-b084089caab0","name":"吳亮慶","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/13%E5%B1%8F%E6%9D%B1%E7%B8%A3/%E5%B1%8F%E6%9D%B1%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"132b3a73cbb10441e2b62d9316fb1831db862536766e14ea378abb1df4663ad1","before_md5":"c2de1c48ca33020d263d786883a6a249","after_text":"（1）監督縣府落實廉能政治，杜絕貪污行為發生。\n（2）督促縣府爭取企業屏東設廠，提供縣民就業機會，減少人口外流。\n（3）建議縣府整體規劃觀光發展方案，爭取觀光客回流。\n（4）屏東縣農漁特產資源豐富，縣府應積極行銷提高農漁民收益。\n（5）監督縣府落實預算執行，避免無謂的浪費。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["監督縣府落實廉能政治，杜絕貪污行為發生。","督促縣府爭取企業屏東設廠，提供縣民就業機會，減少人口外流。","建議縣府整體規劃觀光發展方案，爭取觀光客回流。","屏東縣農漁特產資源豐富，縣府應積極行銷提高農漁民收益。","監督縣府落實預算執行，避免無謂的浪費。"]},{"id":"53275eda-6a42-4ae9-96da-33680d8cf0b1","claim_key":"cec-platform:2022:votetw-candidate-aae07d3499f33eda","person_id":"441a3113-c882-4960-9b44-3aabbf0ba9fc","candidate_id":"cf6e9d64-5dee-4a25-9c10-3310838c2a94","name":"林秉君 kaying．kuying．kalang","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/07%E6%96%B0%E7%AB%B9%E7%B8%A3/%E6%96%B0%E7%AB%B9%E7%B8%A3%E7%AC%AC11%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"9377ff7fe33b3e4c6fb0fee4c5f6d5c9f2e451bddc64d07aef0bbaa28ae5fbe5","before_md5":"6e7ac7cf3fc411a53b620ce0c2f79f80","after_text":"開拓平地原住民族權利與福利發展，全面照顧平地原住民族，具體政見：\n一、教育政策：加強原住民族語言教學工作、廣開原住民族語言教學課程；編列體育及技藝人才培育獎金或健全訓練場域，藉以鼓勵原住民體育及藝術人才。另外，持續推動免費營養午餐、族語教師專職化。\n二、就業經濟政策：督促政府落實原住民族工作權保障法，加強原住民就業媒合服務。扶植原住民各項產業、強化原住民各項職業訓練，打造屬於新竹縣原住民文化創意產業，以改善原住民經濟，提升就業機會。\n三、社會福利政策：督促政府落實原住民福利政策，並協助原住民納入政府多元福利網絡，充份爭取原住民各項社會福利資源，如專業法律諮詢、租屋補助、購屋、修繕、急難救助、婦幼福利及醫療等各項補助經費。\n四、文化傳承政策：為積極發揚本縣原住民優良傳統文化，主張擴大舉辦原住民族文化祭儀等活動，以期保存原住民族文化並向下紮根。各鄉鎮市落實頭目組織常設化，並增列相關預算，強化原住民族文化發展。\n五、族群和諧政策：保障縣內各住民共存共榮，優先照顧資源弱勢、縮短原漢生活差距，共創美好、公義、良善生活圈。\n六、原住民的任何事就是我的事，原住民的小事就是我的大事；在地出身新竹女兒，一通電話到府服務。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","reasonCodes":["heading_or_slogan"],"excludedItemCount":1}},"items":["教育政策：加強原住民族語言教學工作、廣開原住民族語言教學課程；編列體育及技藝人才培育獎金或健全訓練場域，藉以鼓勵原住民體育及藝術人才。另外，持續推動免費營養午餐、族語教師專職化。","就業經濟政策：督促政府落實原住民族工作權保障法，加強原住民就業媒合服務。扶植原住民各項產業、強化原住民各項職業訓練，打造屬於新竹縣原住民文化創意產業，以改善原住民經濟，提升就業機會。","社會福利政策：督促政府落實原住民福利政策，並協助原住民納入政府多元福利網絡，充份爭取原住民各項社會福利資源，如專業法律諮詢、租屋補助、購屋、修繕、急難救助、婦幼福利及醫療等各項補助經費。","文化傳承政策：為積極發揚本縣原住民優良傳統文化，主張擴大舉辦原住民族文化祭儀等活動，以期保存原住民族文化並向下紮根。各鄉鎮市落實頭目組織常設化，並增列相關預算，強化原住民族文化發展。","族群和諧政策：保障縣內各住民共存共榮，優先照顧資源弱勢、縮短原漢生活差距，共創美好、公義、良善生活圈。","原住民的任何事就是我的事，原住民的小事就是我的大事；在地出身新竹女兒，一通電話到府服務。"]},{"id":"13376001-c32f-403b-bced-e4c7531e110c","claim_key":"cec-platform:2022:votetw-candidate-f82202f915e5521b","person_id":"ad730c91-fb65-4755-a6a5-de99cc022154","candidate_id":"d08eac92-139c-413e-917a-659a8242b4d1","name":"孫湯玉惠 aly saku","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/14%E5%AE%9C%E8%98%AD%E7%B8%A3/%E5%AE%9C%E8%98%AD%E7%B8%A3%E7%AC%AC11%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"24de8eebcaf17a17bc6b6d1d11313faa43e393e17336258aed658709c111cf47","before_md5":"5924d9d1f16cda52fd095bf14fc506ba","after_text":"阿歷出力，全「原」給力，「守護族人」五大政見\n一、教育政策：加強落實原住民族語言、文化復振，廣開原住民族語言教學課程，編列族語、體育及樂舞、技藝人才培育獎金，藉以鼓勵原住民語言、體育及樂舞、藝術等專門人才，並建構完善的原住民族教育知識系統及教材以利永續傳承。\n二、就業暨經濟產業政策：督促政府落實原住民族工作權保障法，提供原住民就業媒合服務。扶植原住民各項產業、強化原住民各項職業訓練，培育、輔導原住民青年就業及創造中高齡二度就業之創業機會。爭取發展原住民傳統技藝，多點設立原住民文創商品行銷據點，打造屬於原住民族文創產業，以改善原住民經濟，提升就業機會。建置原住民勞工就業、職能輔導、勞資協調、法律協助與溫暖陪同等全面性的服務平台，讓族人安心就業與生活。\n三、社會福利政策：爭取設置都會區原住民族文化健康站及各區老人日間關懷站、長青食堂等。促政府落實原住民福利政策，積極爭取原住民各項社會福利資源，法律諮詢、租屋補助、購屋、修繕、急難救助、婦幼福利及醫療等各項補助經費。\n四、文化傳承政策：持續爭取原住民族多功能會館前方建構原住民族多元文化主題公園。強化原住民族文化發展，並爭取提高編列原住民族教育、文化、歲時祭儀、體育、樂舞藝術發展等活動經費，增列相關預算以保存發揚原住民族傳統文化，提昇原住民族發展協會、社團辦理活動能力等。\n五、族群共融政策：持續要求辦理宜蘭縣都會區原住民遷移史紀錄計畫，以利未來列入宜蘭縣史，補足都會區各原住民族群遷移至宜蘭的文史紀錄。建構安全、便宜及便利之租屋服務平台，並爭取建立原住民安全社會住宅政策，讓族人安居樂業，實現居住正義。保障縣內各住民共榮，優先照顧資源弱勢、縮短原漢生活差距，共創美好、公義、良善生活。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","reasonCodes":["heading_or_slogan"],"excludedItemCount":1}},"items":["教育政策：加強落實原住民族語言、文化復振，廣開原住民族語言教學課程，編列族語、體育及樂舞、技藝人才培育獎金，藉以鼓勵原住民語言、體育及樂舞、藝術等專門人才，並建構完善的原住民族教育知識系統及教材以利永續傳承。","就業暨經濟產業政策：督促政府落實原住民族工作權保障法，提供原住民就業媒合服務。扶植原住民各項產業、強化原住民各項職業訓練，培育、輔導原住民青年就業及創造中高齡二度就業之創業機會。爭取發展原住民傳統技藝，多點設立原住民文創商品行銷據點，打造屬於原住民族文創產業，以改善原住民經濟，提升就業機會。建置原住民勞工就業、職能輔導、勞資協調、法律協助與溫暖陪同等全面性的服務平台，讓族人安心就業與生活。","社會福利政策：爭取設置都會區原住民族文化健康站及各區老人日間關懷站、長青食堂等。促政府落實原住民福利政策，積極爭取原住民各項社會福利資源，法律諮詢、租屋補助、購屋、修繕、急難救助、婦幼福利及醫療等各項補助經費。","文化傳承政策：持續爭取原住民族多功能會館前方建構原住民族多元文化主題公園。強化原住民族文化發展，並爭取提高編列原住民族教育、文化、歲時祭儀、體育、樂舞藝術發展等活動經費，增列相關預算以保存發揚原住民族傳統文化，提昇原住民族發展協會、社團辦理活動能力等。","族群共融政策：持續要求辦理宜蘭縣都會區原住民遷移史紀錄計畫，以利未來列入宜蘭縣史，補足都會區各原住民族群遷移至宜蘭的文史紀錄。建構安全、便宜及便利之租屋服務平台，並爭取建立原住民安全社會住宅政策，讓族人安居樂業，實現居住正義。保障縣內各住民共榮，優先照顧資源弱勢、縮短原漢生活差距，共創美好、公義、良善生活。"]},{"id":"f4db64dc-ed67-4993-b5d2-5f04136fa950","claim_key":"cec-platform:2022:votetw-candidate-3f0b69981320dd7b","person_id":"d235cfca-97cf-4ad5-a39e-d3423a86ff1e","candidate_id":"d56ee5ae-e5ae-4285-bd8d-5ec160a443f8","name":"陳海山","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/17%E6%BE%8E%E6%B9%96%E7%B8%A3/%E6%BE%8E%E6%B9%96%E7%B8%A3%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"c9aaaf6c72d2713702c0c6972ecd2623433b8ae7f029e561144dca9cba9877d8","before_md5":"1178c8e0c39d3be981214fec1637f16f","after_text":"督促縣長，履行對縣民的承諾\n服務不分大小事","split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"},"items":["督促縣長，履行對縣民的承諾","服務不分大小事"]},{"id":"bb4eeaa3-33e7-44f3-9485-f09a24a68f75","claim_key":"cec-platform:2022:votetw-candidate-2c04857a76c12278","person_id":"f35edeb7-f6e1-4144-ad0a-5ab314889b20","candidate_id":"d99aa623-c277-4831-8069-d2a5bbc8106e","name":"哈尼．噶照 Hani Kacaw","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC4-7%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"3e18152df0f2747ab2140e704cec47ead28ebe3095eae2f9ee5d1a4e70b7cbda","before_md5":"ab802934d18013faf9ff0d47c70e12c8","after_text":"1. 爭取原住民族傳統競技、體育發展、培育原住民運動專業人才預算經費提昇。\n2. 督促政府活化原鄉學校閒置空間，積極發展老幼共學環境。\n3. 督促政府扶植原住民各項產業、強化原住民各項職業訓練，打造屬於花蓮縣原住民族文化創意產業，以改善原住民經濟，提升就業機會。\n4. 加速推動設立「原住民流行音樂基地」，透過音樂活動爭取文創產業能見度，吸引流行音樂產業匯聚，打造花蓮縣成為太平洋左岸音樂重鎮。\n5. 支持原鄉回流青年，督促政府培植輔導跨部落原住民族青農或創農企業，推動跨部落休閒農業連結。\n6. 協助原鄉爭取交通基礎建設經費，逐步改善各部落農路及主要聯絡道路，以維護鄉親生命財產安全。\n7. 督促縣府加強原鄉醫療服務，強化老人照護並落實急難救助等社會福利。\n8. 督促政府落實「一部落一聚會所」，促成各部落聚會所工程如期如質完工，以提供部落族人優質的生活休憩與歲時祭儀活動空間。\n9. 督促政府推動與建構完善之民族教育政策，提升族語文化的地位。\n10. 推展原住民技職教育，輔導取得各職類技能證照，爭取企業民間等實習實戰經驗以利未來求職及創業。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["爭取原住民族傳統競技、體育發展、培育原住民運動專業人才預算經費提昇。","督促政府活化原鄉學校閒置空間，積極發展老幼共學環境。","督促政府扶植原住民各項產業、強化原住民各項職業訓練，打造屬於花蓮縣原住民族文化創意產業，以改善原住民經濟，提升就業機會。","加速推動設立「原住民流行音樂基地」，透過音樂活動爭取文創產業能見度，吸引流行音樂產業匯聚，打造花蓮縣成為太平洋左岸音樂重鎮。","支持原鄉回流青年，督促政府培植輔導跨部落原住民族青農或創農企業，推動跨部落休閒農業連結。","協助原鄉爭取交通基礎建設經費，逐步改善各部落農路及主要聯絡道路，以維護鄉親生命財產安全。","督促縣府加強原鄉醫療服務，強化老人照護並落實急難救助等社會福利。","督促政府落實「一部落一聚會所」，促成各部落聚會所工程如期如質完工，以提供部落族人優質的生活休憩與歲時祭儀活動空間。","督促政府推動與建構完善之民族教育政策，提升族語文化的地位。","推展原住民技職教育，輔導取得各職類技能證照，爭取企業民間等實習實戰經驗以利未來求職及創業。"]},{"id":"0999d617-33da-4887-ab09-2505e4184fb8","claim_key":"cec-platform:2022:votetw-candidate-e123cb9212703f44","person_id":"d4a647ad-40db-4b1d-a6f0-8196988085f4","candidate_id":"d9b15865-0794-411d-bf98-72772659919b","name":"陳毓仁","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/17%E6%BE%8E%E6%B9%96%E7%B8%A3/%E6%BE%8E%E6%B9%96%E7%B8%A3%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"c9aaaf6c72d2713702c0c6972ecd2623433b8ae7f029e561144dca9cba9877d8","before_md5":"91866ddaf765fe244aaf75723341dcd4","after_text":"海洋生態永續發展\n推動秋冬觀光賽事活動\n教育語言多元化發展\n優化長照、弱勢照顧","split":{"method":"manually_reviewed_platform_snapshot","version":"election-content-items-v1","confidence":100,"reviewStatus":"reviewed"},"items":["海洋生態永續發展","推動秋冬觀光賽事活動","教育語言多元化發展","優化長照、弱勢照顧"]},{"id":"98a6f0ba-1061-445e-b34a-0e6d7c140b98","claim_key":"cec-platform:2022:votetw-candidate-123959c0b20e11d7","person_id":"b1ba40ee-4d95-4a5d-b307-e6d2bc191b12","candidate_id":"da279275-2c60-45c5-9324-4cbefe430399","name":"許展維","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/13%E5%B1%8F%E6%9D%B1%E7%B8%A3/%E5%B1%8F%E6%9D%B1%E7%B8%A3%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"c4ec4b59e24163526e3504f3d7b798532fafa689f63bcb9ab9e35628d7665151","before_md5":"bdd6b6800c02c194fb3df836480e92b9","after_text":"一、堅持清廉、勤政、愛鄉土之從政理念，捍衛台灣主權，堅持國家主體性。\n二、支持「屏東向前、打造希望城市」之理念推動縣政，包括留縣升學、返鄉就業、在地安養、藝文發展、重大交通建設、醫療產業升級。\n三、秉持著公平正義的精神，維護社會安全，並強化本土基礎教育。\n四、擴大照顧新住民、單親、隔代教養及脆弱家庭等希望學童之課後輔導與學習。\n五、協助整合政府與民間之慈善團體資源，對於弱勢家庭及邊緣戶能提供更有效率、實際之幫助。\n六、促進萬丹、新園、東港三鄉鎮之在地觀光產業，將宗教節慶、藝術文化、自然生態及人文景觀做串連性整體規劃，以發展在地特色觀光。\n七、推行萬丹鄉設置農特產品展售中心，透過改善農產品品質、升級農業生物科技產業及紮實農業結構，保留傳統農業精神，支持在地青農轉型農業經營型態，並朝向永續發展之價值。\n八、開創新園鄉社區總體營造，落實社區福利制度之完整。協助漁村新興觀光產業之活絡，督促開發鹽埔漁港，以增加在地就業機會。\n九、振興東港鎮觀光產業，將特色美食、在地宗教文化慶典以及地方觀光景點行銷至國際。\n十、重視校園安全，積極爭取經費改善校園軟硬體設施之完善；維護鄉鎮道路安全，爭取地方公共建設，照顧人民權益。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["堅持清廉、勤政、愛鄉土之從政理念，捍衛台灣主權，堅持國家主體性。","支持「屏東向前、打造希望城市」之理念推動縣政，包括留縣升學、返鄉就業、在地安養、藝文發展、重大交通建設、醫療產業升級。","秉持著公平正義的精神，維護社會安全，並強化本土基礎教育。","擴大照顧新住民、單親、隔代教養及脆弱家庭等希望學童之課後輔導與學習。","協助整合政府與民間之慈善團體資源，對於弱勢家庭及邊緣戶能提供更有效率、實際之幫助。","促進萬丹、新園、東港三鄉鎮之在地觀光產業，將宗教節慶、藝術文化、自然生態及人文景觀做串連性整體規劃，以發展在地特色觀光。","推行萬丹鄉設置農特產品展售中心，透過改善農產品品質、升級農業生物科技產業及紮實農業結構，保留傳統農業精神，支持在地青農轉型農業經營型態，並朝向永續發展之價值。","開創新園鄉社區總體營造，落實社區福利制度之完整。協助漁村新興觀光產業之活絡，督促開發鹽埔漁港，以增加在地就業機會。","振興東港鎮觀光產業，將特色美食、在地宗教文化慶典以及地方觀光景點行銷至國際。","重視校園安全，積極爭取經費改善校園軟硬體設施之完善；維護鄉鎮道路安全，爭取地方公共建設，照顧人民權益。"]},{"id":"bce09751-57bd-4b91-a8e1-a3c38c9b8ccb","claim_key":"cec-platform:2022:votetw-candidate-d0658e092d8d6486","person_id":"8dabb704-79c5-481c-a7bb-5bf2fc848272","candidate_id":"e8ca7231-0e3b-4873-a094-08aff4842561","name":"周陳曉玟","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/13%E5%B1%8F%E6%9D%B1%E7%B8%A3/%E5%B1%8F%E6%9D%B1%E7%B8%A3%E7%AC%AC8%E3%80%8113-16%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"524f9657b4af1b226a4926022ada959412ea2880d9650209ddd4123156215480","before_md5":"ae2576337f5a553dad593e7c569a70d9","after_text":"一、縣議員補助款有基礎建設補助、設備補助、活動補助三種，我將以公開透明的方式，每個月公佈補助用途、金額。\n二、監督縣政府，來自中央的統籌分配款必須按春日鄉的分配公式，全數撥入原鄉鄉公所。\n三、監督縣政府，來自中央的計畫型補助經費應按計畫目的撥入原鄉鄉公所執行，不得挪為縣政府煙火活動用途。\n四、屏東縣求職不易、人口流失，原鄉尤其嚴重。要求縣政府「勞動暨青年發展處」提出促進就業方案，並每個月公佈就業績效。\n五、屏東原鄉多為小農旱作，銷售不易。要求縣政府「農業處」提出原鄉農產品促銷方案，並每個月公佈促銷績效。\n六、媒合社會慈善團體，針對原鄉老弱病殘進行長期扶助專案。\n七、與立法委員高金素梅成立聯合服務處，從中央到地方，聯手監督政府，聯手服務鄉民。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["縣議員補助款有基礎建設補助、設備補助、活動補助三種，我將以公開透明的方式，每個月公佈補助用途、金額。","監督縣政府，來自中央的統籌分配款必須按春日鄉的分配公式，全數撥入原鄉鄉公所。","監督縣政府，來自中央的計畫型補助經費應按計畫目的撥入原鄉鄉公所執行，不得挪為縣政府煙火活動用途。","屏東縣求職不易、人口流失，原鄉尤其嚴重。要求縣政府「勞動暨青年發展處」提出促進就業方案，並每個月公佈就業績效。","屏東原鄉多為小農旱作，銷售不易。要求縣政府「農業處」提出原鄉農產品促銷方案，並每個月公佈促銷績效。","媒合社會慈善團體，針對原鄉老弱病殘進行長期扶助專案。","與立法委員高金素梅成立聯合服務處，從中央到地方，聯手監督政府，聯手服務鄉民。"]},{"id":"0b8d1d5b-a99c-4bd6-b110-ae33251a6539","claim_key":"cec-platform:2022:votetw-candidate-98808e5a0b59e08c","person_id":"200841f4-1391-4685-8d3e-a1ef312b0bce","candidate_id":"ee3f9dbd-8f9c-46ef-941a-2fdb6ccf2c92","name":"洪宗麒","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/13%E5%B1%8F%E6%9D%B1%E7%B8%A3/%E5%B1%8F%E6%9D%B1%E7%B8%A3%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"c4ec4b59e24163526e3504f3d7b798532fafa689f63bcb9ab9e35628d7665151","before_md5":"dd0f06af86e87e515806895f999f6054","after_text":"一、宗麒熱心專業協助民眾爭議調解，連續7年獲得「縣長獎」肯定，並多次取得全縣第一榮譽，7年多完成近400件調解案件，本於服務社會精神，持續協助民眾解決難題。\n二、宗麒號召「萬丹青年軍公益團隊」近4年已協助逾250件弱勢家庭急難救助，將透過整合社福資源，協助遭遇困難民眾渡過難關。\n三、爭取提高社會福利預算，扶助弱勢家庭及社福團體。\n四、爭取弱勢家庭學童助學預算，讓學習資源沒有差距、起跑沒有差異。\n五、整合行銷萬丹、新園觀光資源，串連東港推動觀光旅遊帶，活化地方創造就業。\n六、爭取落實延長幼托「課後照顧」時間，減輕家庭照顧壓力，讓家長安心工作。\n七、爭取經費改善社區老人福利、協助社福團體關懷弱勢長者。\n八、監督縣政，爭取基礎建設，提升居住品質。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["宗麒熱心專業協助民眾爭議調解，連續7年獲得「縣長獎」肯定，並多次取得全縣第一榮譽，7年多完成近400件調解案件，本於服務社會精神，持續協助民眾解決難題。","宗麒號召「萬丹青年軍公益團隊」近4年已協助逾250件弱勢家庭急難救助，將透過整合社福資源，協助遭遇困難民眾渡過難關。","爭取提高社會福利預算，扶助弱勢家庭及社福團體。","爭取弱勢家庭學童助學預算，讓學習資源沒有差距、起跑沒有差異。","整合行銷萬丹、新園觀光資源，串連東港推動觀光旅遊帶，活化地方創造就業。","爭取落實延長幼托「課後照顧」時間，減輕家庭照顧壓力，讓家長安心工作。","爭取經費改善社區老人福利、協助社福團體關懷弱勢長者。","監督縣政，爭取基礎建設，提升居住品質。"]},{"id":"b4a88648-bb17-41c8-a465-f4b33df5ab6f","claim_key":"cec-platform:2022:votetw-candidate-64a896709e62ba7a","person_id":"7d3b60d1-a527-4ba7-ae8a-ba83edde4d4a","candidate_id":"f012bdcb-c960-4f24-a87d-ea9737392736","name":"武清山","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC07%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"d70c855972384586ff4d35f2dc8e60084c700ae0d9a1b406c3e8b719b4a3858c","before_md5":"40939ef2c278941b42c4c184b3631a51","after_text":"1. 堅守原住民文化，捍衛原住民權益，監督縣政，為民喉舌，爭取鄉親福祉。\n2. 促請縣府重視原住民母語教學課程，培訓原住民教師，以彌補山區老師嚴重不足的情況。\n3. 加強都市原住民文化會館周邊設施，完善館內設備，使都市原住民有良好的文化傳授、技藝學習、聚會活動的場所。\n4. 繼續爭取經費落實基礎建設，改善各村農路，提升飲水品質，健全消防系統，培訓體育人才，強化電力與電信功能，並積極爭取野溪整治及曾文溪護岸工程，以維護鄉親生命財產安全。\n5. 繼續爭取山美至里佳道路開通工程，完善鄉內道路連貫系統。\n6. 督請縣府將169線納入生活圈道路，並改善129線急彎路段及改善155線、149甲線等鄉內主要道路。\n7. 督請縣府加強山區醫療服務，加強老人照護，增加生產補助並落實急難救助等社會福利。\n8. 促請縣府重視觀光、文化、農特產及原住民傳統技藝等各項產業發展，配合部落特色，營造部落企業，繁榮地方經濟。\n9. 促請縣府寬列經費補助原住民各歲時祭儀及文化活動。\n10. 督請縣府重視遷徙至永久屋鄉親的各項權益，並輔導就業及協助發展永久屋之各項產業。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["堅守原住民文化，捍衛原住民權益，監督縣政，為民喉舌，爭取鄉親福祉。","促請縣府重視原住民母語教學課程，培訓原住民教師，以彌補山區老師嚴重不足的情況。","加強都市原住民文化會館周邊設施，完善館內設備，使都市原住民有良好的文化傳授、技藝學習、聚會活動的場所。","繼續爭取經費落實基礎建設，改善各村農路，提升飲水品質，健全消防系統，培訓體育人才，強化電力與電信功能，並積極爭取野溪整治及曾文溪護岸工程，以維護鄉親生命財產安全。","繼續爭取山美至里佳道路開通工程，完善鄉內道路連貫系統。","督請縣府將169線納入生活圈道路，並改善129線急彎路段及改善155線、149甲線等鄉內主要道路。","督請縣府加強山區醫療服務，加強老人照護，增加生產補助並落實急難救助等社會福利。","促請縣府重視觀光、文化、農特產及原住民傳統技藝等各項產業發展，配合部落特色，營造部落企業，繁榮地方經濟。","促請縣府寬列經費補助原住民各歲時祭儀及文化活動。","督請縣府重視遷徙至永久屋鄉親的各項權益，並輔導就業及協助發展永久屋之各項產業。"]},{"id":"d2366ece-d3c4-4437-9d42-2961650b4701","claim_key":"cec-platform:2022:votetw-candidate-c807a04141434e5f","person_id":"a55270f6-b540-4739-a98f-a4d58d92b9ac","candidate_id":"f08c59b7-d811-4f07-8222-b02e918ab7dc","name":"陳明建","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%80%E9%81%B8%E5%8D%80.pdf","source_sha256":"bea300424de713c67b25e23089e5715a8697f53ff1b4ec2c3afa955681c159d5","before_md5":"34bd7eb73cc070077eddc0420a89e3fd","after_text":"用心服務、守護原民\n• 增編年度經費及地區協進會活動經費。\n• 文化：增編經費、推展族語、傳承傳統手工藝、促進都市原鄉交流。\n• 教育：兒童課輔、充實原民教育課程、推展部大教育取得大專學位、原住民子女教育獎助學金、持續爭取原住民部落大學經費。\n• 幼老：增加育兒津貼、托育津貼補助、幼教福利；關懷長者，增設「文化健康站」、老人假牙補助。\n• 青年：設立青創基地、青年會議、觀摩交流、原植培力青年。\n• 勞工：安全衛生講座、職安卡訓練、勞工權益安全網。\n• 社福：原住民微型意外險續辦（免保費、團保）、房屋建構及修繕補助、租屋租金補貼、健保自行額補助。\n• 就業：就業媒合、職業訓練、暑期大專工讀、婦女創業研習班、職業汽車訓練補助、取得專業級證照市府補助。\n• 體育：增編體育經費、促進縣市交流、培植原民體育人才、辦理各項體育活動。\n• 經建：爭取「一區一聚會所」、爭取七堵社會住宅原住民保留戶、改善會館週邊環境、完成地區經建設備。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved","releaseQuality":{"version":"platform-fulfillment-release-v1","reasonCodes":["heading_or_slogan"],"excludedItemCount":2}},"items":["文化：增編經費、推展族語、傳承傳統手工藝、促進都市原鄉交流。","教育：兒童課輔、充實原民教育課程、推展部大教育取得大專學位、原住民子女教育獎助學金、持續爭取原住民部落大學經費。","幼老：增加育兒津貼、托育津貼補助、幼教福利；關懷長者，增設「文化健康站」、老人假牙補助。","青年：設立青創基地、青年會議、觀摩交流、原植培力青年。","勞工：安全衛生講座、職安卡訓練、勞工權益安全網。","社福：原住民微型意外險續辦（免保費、團保）、房屋建構及修繕補助、租屋租金補貼、健保自行額補助。","就業：就業媒合、職業訓練、暑期大專工讀、婦女創業研習班、職業汽車訓練補助、取得專業級證照市府補助。","體育：增編體育經費、促進縣市交流、培植原民體育人才、辦理各項體育活動。","經建：爭取「一區一聚會所」、爭取七堵社會住宅原住民保留戶、改善會館週邊環境、完成地區經建設備。"]},{"id":"dde23055-bc85-4785-adfe-5c6763588130","claim_key":"cec-platform:2022:votetw-candidate-1fb729969067394f","person_id":"e5b8c8a5-aa13-4a5c-93d8-b220f1133886","candidate_id":"f99bc853-2f0e-40f0-a672-c4da47e1b970","name":"蔡信典","source_url":"https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC05%E9%81%B8%E8%88%89%E5%8D%80.pdf","source_sha256":"60e9846e0d1d9a9678151bbaa7c214bcc3b092eae0e3fa61d310153ff6579337","before_md5":"f52d80a57fbcbdf9937407dab79a0734","after_text":"一、堅持正直、重義、同理心的服務理念，為布袋、義竹鄉親打拼。\n二、堅持監督縣政平衡發展，維護布袋、義竹鄉親、新住民同胞應得的權益。\n三、堅持督促縣府推動科技農漁牧業，有效提升產值、減少勞動力付出，並降低損害，藏富於鄉親。\n四、堅持督促縣府落實並提升長照、日托服務，確實照顧、維護鄉親幸福、安心的生活。\n五、堅持督促縣府徹底改善區域、村里及農漁排水，有效解決社區及農漁牧產業，免除鄉親水患苦境。\n六、堅持持續督促縣府加強廣設路口監視系統及照明設備，維護社區治安，讓鄉親安居樂業。\n七、堅持爭取資源，致力發展布袋、義竹觀光產業，並推展在地特色宗教、民俗、文化與藝文活動。\n八、堅持制訂政策，結合政府、慈善團體資源，強化弱勢鄉親服務與照顧。","split":{"method":"numbered","version":"election-content-items-v1","confidence":98,"reviewStatus":"auto_approved"},"items":["堅持正直、重義、同理心的服務理念，為布袋、義竹鄉親打拼。","堅持監督縣政平衡發展，維護布袋、義竹鄉親、新住民同胞應得的權益。","堅持督促縣府推動科技農漁牧業，有效提升產值、減少勞動力付出，並降低損害，藏富於鄉親。","堅持督促縣府落實並提升長照、日托服務，確實照顧、維護鄉親幸福、安心的生活。","堅持督促縣府徹底改善區域、村里及農漁排水，有效解決社區及農漁牧產業，免除鄉親水患苦境。","堅持持續督促縣府加強廣設路口監視系統及照明設備，維護社區治安，讓鄉親安居樂業。","堅持爭取資源，致力發展布袋、義竹觀光產業，並推展在地特色宗教、民俗、文化與藝文活動。","堅持制訂政策，結合政府、慈善團體資源，強化弱勢鄉親服務與照顧。"]}]$repairs$::jsonb)
 AS r(id uuid,claim_key text,person_id uuid,candidate_id uuid,name text,source_url text,source_sha256 text,before_md5 text,after_text text,split jsonb,items jsonb);
DO $guard$
BEGIN
 IF (SELECT count(*) FROM platform_text_repairs)<>58 OR (SELECT count(DISTINCT id) FROM platform_text_repairs)<>58 THEN
  RAISE EXCEPTION 'Unexpected reviewed text scope';
 END IF;
 IF EXISTS (
 SELECT 1 FROM platform_text_repairs r LEFT JOIN public.person_claims c ON c.id=r.id
 LEFT JOIN public.candidates candidate ON candidate.id=c.candidate_id
 LEFT JOIN public.person_canonical_map cm ON cm.person_id=candidate.person_id
 LEFT JOIN public.person_canonical_map pm ON pm.person_id=c.person_id
 LEFT JOIN public.races race ON race.id=candidate.race_id
 LEFT JOIN public.elections election ON election.id=race.election_id
 WHERE c.id IS NULL OR c.claim_key IS DISTINCT FROM r.claim_key OR c.person_id IS DISTINCT FROM r.person_id
 OR c.candidate_id IS DISTINCT FROM r.candidate_id OR c.source_url IS DISTINCT FROM r.source_url
 OR c.claim_json#>>'{sourceDocument,sha256}' IS DISTINCT FROM r.source_sha256
 OR c.claim_type IS DISTINCT FROM 'platform' OR c.review_status IS DISTINCT FROM 'verified'
 OR c.visibility IS DISTINCT FROM 'public' OR c.is_public IS DISTINCT FROM true
 OR coalesce(cm.canonical_person_id,candidate.person_id) IS DISTINCT FROM coalesce(pm.canonical_person_id,c.person_id)
 OR candidate.is_elected IS DISTINCT FROM true OR candidate.election_result IS DISTINCT FROM 'elected'
 OR election.year IS DISTINCT FROM 2022 OR race.race_type IS DISTINCT FROM 'councilor_district'
 OR c.claim_json->'items' IS DISTINCT FROM r.items OR c.claim_json->'contentSplit' IS DISTINCT FROM r.split
 OR md5(coalesce(c.claim_value,'')) NOT IN (r.before_md5,md5(r.after_text))
 OR md5(coalesce(c.claim_json->>'platformText','')) NOT IN (r.before_md5,md5(r.after_text))
 ) THEN RAISE EXCEPTION 'Reviewed platform baseline changed; reconcile before applying'; END IF;
END;
$guard$;
UPDATE public.person_claims c SET claim_value=r.after_text,
 claim_json=jsonb_set(c.claim_json,'{platformText}',to_jsonb(r.after_text)),updated_at=now()
FROM platform_text_repairs r WHERE c.id=r.id AND
 (c.claim_value IS DISTINCT FROM r.after_text OR c.claim_json->>'platformText' IS DISTINCT FROM r.after_text);
DO $verify$
BEGIN
 IF EXISTS(SELECT 1 FROM platform_text_repairs r JOIN public.person_claims c ON c.id=r.id
 WHERE c.claim_value IS DISTINCT FROM r.after_text OR c.claim_json->>'platformText' IS DISTINCT FROM r.after_text
 OR c.claim_json->'items' IS DISTINCT FROM r.items OR c.claim_json->'contentSplit' IS DISTINCT FROM r.split) THEN
 RAISE EXCEPTION 'Reviewed text reconciliation verification failed'; END IF;
END;
$verify$;
COMMIT;
